/* بيانات قسم ruqya: تُحمَّل عند أول فتح للقسم */
window.RUQYA = {"ch":[{"id":"taarif","t":"تعريف الرقية الشرعية وأدلتها من القرآن والسنة","d":"الرقية الشرعية قراءة أو دعاء أو ذكر يُقصد به طلب الشفاء أو الحفظ من الله تعالى، بكلام الله وأسمائه وصفاته والأدعية الثابتة، مع اعتقاد أن الشافي هو الله وحده. وهذا الباب يبين معناها، وأدلة مشروعيتها من الكتاب والسنة، وما يخرج عنها.","blocks":[["sub","ما معنى الرقية الشرعية؟"],["p","الرقية في الاستعمال الشرعي هي العُوذة والقراءة التي يُطلب بها الشفاء من مرض أو أذى كلدغة وعين وحمى، أو الحفظ منه قبل وقوعه. وتكون «شرعية» إذا اجتمع فيها ثلاثة أمور: أن تكون بكلام الله أو أسمائه وصفاته أو بالأدعية الثابتة، وأن تكون بلسان مفهوم المعنى، وأن يعتقد الراقي والمرقي أنها سبب لا تؤثر بذاتها، وأن النفع والضر بيد الله."],["sub","الفرق بين مصطلحات الباب"],["list","ruq-rules",[["الرقية","أن يقرأ المرء على نفسه أو على غيره ما ثبت أو ما كان مشروعاً من القرآن والأذكار، طلباً للشفاء أو الحفظ.",["ardu"]],["الاسترقاء","أن يطلب المريض أو أهله من غيره أن يرقيه. وهو جائز، وتركه توكلاً أفضل لمن قدر عليه كما في حديث السبعين ألفاً.",["sabeen"]],["التميمة والتولة","خرزات وأوراق وحروز تُعلَّق لدفع الضر، وما يُصنع لتحبيب الزوجين بالسحر. جاء النص بأنها شرك، فلا تدخل في الرقية الشرعية.",["shirk"]],["الطب والعلاج","الرقية لا تنافي الدواء، بل هما من هدي النبي ﷺ معاً. وقد أمر بالتداوي.",["tadawaw"]]]],["sub","أدلة المشروعية من القرآن الكريم"],["p","وصف الله القرآن بأنه شفاء ورحمة في ستة مواضع، وأمر بالاستعاذة به من الشيطان في سورتين عظيمتين، وبيّن أن للشيطان نزغاً وطائفاً يُدفع بالذكر. وتفصيل آيات الشفاء الست في باب «القرآن شفاء»، وما يُرقى به من السور في باب «ما يُرقى به»."],["links",[["asl","آيات الشفاء الست: الإسراء 82، يونس 57، فصلت 44، التوبة 14، النحل 69، الشعراء 80"],["ruqa","الفاتحة والمعوذات وآية الكرسي وخواتيم البقرة"]]],["sub","أدلة المشروعية من السنة النبوية"],["p","ثبتت الرقية بالقرآن قولاً وفعلاً وإقراراً: فرقى النبي ﷺ نفسه وأهله، ورقاه جبريل عليه السلام، وأقر الصحابة على الرقية بالفاتحة وقال: «وما يدريك أنها رقية»، وجعل أخذ الأجر عليها حلالاً. وهذه جملة أدلتها:"],["links",[["sunna","الرقية في السنة الصحيحة: الفاتحة، والمعوذات، ورقية جبريل، و«أذهب الباس»، ووضع اليد على موضع الألم"]]],["h",["ajr","jann","aidh"]],["sub","حدود المشروعية"],["p","الأصل الجامع قوله ﷺ: «اعرضوا عليّ رقاكم، لا بأس بالرقى ما لم يكن فيه شرك». فكل رقية خلت من الشرك، وفُهم معناها، واعتُقد أن الشفاء من الله، فهي جائزة، وما سواها فمردود. وتفصيل الشروط في باب «ضوابط الرقية المشروعة»."]]},{"id":"anwaa","t":"أنواع الرقية الشرعية","d":"تتنوع الرقية الشرعية بحسب ما يُرقى به (آيات القرآن، أدعية نبوية، أسماء الله الحسنى) وبحسب الغرض (علاج أو وقاية) وبحسب الهيئة (قراءة ونفث ومسح ودعاء). وكل نوع هنا مبني على نص ثابت.","blocks":[["sub","أولاً: الرقية بآيات القرآن وسوره"],["list","ruq-steps",[["سورة الفاتحة","أشهر ما رُقي به، وقد أقرّ النبي ﷺ الصحابي الذي رقى بها اللديغ.",["fatiha"]],["المعوذات (الإخلاص والفلق والناس)","كان ﷺ إذا مرض نفث على نفسه بالمعوذات، وإذا أوى إلى فراشه جمع كفيه ونفث فيهما وقرأ بها ومسح جسده.",["muawwidhat","nawm"]],["آية الكرسي","حفظ من الشيطان لمن قرأها عند النوم.",["kursi"]],["خواتيم سورة البقرة","من قرأ بالآيتين من آخر البقرة في ليلة كفتاه.",["baqara"]]]],["sub","ثانياً: الرقية بالأدعية النبوية"],["list","ruq-steps",[["«بسم الله أرقيك من كل شيء يؤذيك»","رقية جبريل للنبي ﷺ، وفيها طلب الشفاء من شر كل نفس وعين حاسد.",["jibril"]],["«اللهم رب الناس أذهب الباس»","دعاء كان النبي ﷺ يقوله للمريض، وفيه أن الشافي هو الله لا شفاء إلا شفاؤه.",["adhhib"]],["وضع اليد على موضع الألم","يقول المريض: بسم الله ثلاثاً، ثم يقول سبعاً: أعوذ بالله وقدرته من شر ما أجد وأحاذر.",["yad"]],["«أسأل الله العظيم رب العرش العظيم أن يشفيك»","يقولها زائر المريض سبع مرات.",["shifa7"]],["«أعيذكما بكلمات الله التامة»","تعويذة الأولاد من كل شيطان وهامة وعين لامة.",["aidh"]]]],["h",["shifa7"]],["sub","ثالثاً: الرقية بأسماء الله وصفاته"],["p","أمر الله بدعائه بأسمائه الحسنى، فيُرقى بها كما في «بسم الله»، و«أعوذ بعزة الله وقدرته»، و«أعوذ بكلمات الله التامة»، و«الله يشفيك»؛ فهي من التوسل بأسمائه وصفاته. أما حروف بلا معنى ولا يُفهم فليست منه."],["ay",[{"t":"ولله الأسماء الحسنى فادعوه بها","r":[7,180],"n":"الأسماء الحسنى وسيلة للدعاء، فيُختار منها ما يناسب المطلوب: «الشافي» لطلب الشفاء، و«الحفيظ» للحفظ."},{"t":"قل ادعوا الله أو ادعوا الرحمن أيا ما تدعوا فله الأسماء الحسنى","r":[17,110],"n":"الدعاء بأي اسم من أسماء الله الحسنى جائز، وفي الباب ما ورد بنص ثابت."}]],["links",[["asma","أسماء الله الحسنى في القرآن الكريم"]]],["sub","رابعاً: أنواع الرقية بحسب الغرض"],["list","ruq-steps",[["رقية العلاج","تُقرأ على المريض بعد وقوع المرض أو الأذى، كالفاتحة على اللديغ. ولا تُغني عن الطبيب.",["fatiha"]],["رقية العين","يُرقى من أصابته العين بالمعوذات وما ثبت، وقد رُخص فيها.",["ayn","rukhsa"]],["رقية الوقاية والتحصين","تُقرأ قبل وقوع الأذى: أذكار الصباح والمساء والنوم. وتفصيلها في باب «كيفية التحصن».",["nawm"]],["رقية السحر والمس","يُرقى المسحور بآيات إبطال السحر وآيات التعوذ، مع ملازمة الأذكار والرجوع إلى الله. وليس فيها نص مرفوع في تعيين آيات بعينها، فيُلتزم بالقرآن عامة.",["ardu"]]]],["sub","خامساً: أنواع الرقية بحسب الهيئة"],["list","ruq-steps",[["القراءة مع النفث والمسح","ينفث القارئ نفثاً خفيفاً مع شيء يسير من الريق ويمسح بيده على موضع الألم أو على الجسد. وكان ﷺ يفعله بالمعوذات.",["muawwidhat"]],["الرقية بالتفل","ثبت في رقية الفاتحة أنه جعل يتفل ويقرأ الفاتحة.",["fatiha"]],["الدعاء مع وضع اليد","يضع الراقي يده على موضع الألم ويدعو.",["yad"]]]],["p","ولم أجد في الكتب الستة المضمّنة نصاً صحيحاً مرفوعاً في هيئات أخرى كقراءة في ماء أو زيت ثم شربه أو الاغتسال به؛ وقد اختلف فيه أهل العلم، فيُقتصر على الوارد، ويُسأل أهل العلم فيما سواه."]]},{"id":"muaalij","t":"أنواع المعالجين ومعايير التمييز بينهم","d":"ليس كل من تصدى للرقية راقياً شرعياً. بين الطبيب المسلم والراقي الشرعي الضابط من جهة، والدجال والكاهن والساحر والمستعين بالجن من جهة أخرى مراتب. وهذا الباب يبين كل صنف وحكمه بدليله، ويضع معايير واضحة تحمي المريض من الدجل.","blocks":[["sub","أولاً: أصناف من يتصدى للعلاج"],["cards",[{"t":"الطبيب المسلم المختص","tag":"مشروع","cls":"ok","d":"يعالج الأمراض العضوية والنفسية بالأسباب الحسية، وهو مأمور به. والرقية لا تحل محله ولا تؤخر مراجعته.","ev":["tadawaw"]},{"t":"الراقي الشرعي الضابط","tag":"مشروع","cls":"ok","d":"يرقي بالقرآن والأذكار الثابتة بلسان مفهوم، ويعتقد أن الشافي هو الله، ويعرف حدوده فلا يدعي علم الغيب ولا يضر المريض، ويأخذ أجراً معتدلاً إن أخذ.","ev":["ardu","fatiha","ajr"]},{"t":"الراقي المقصّر أو الجاهل","tag":"يُنصح ويُترك إن أصرّ","cls":"mid","d":"يرقي بالقرآن لكنه يخطئ في الضوابط: يصرخ ويضرب المريض بدعوى إخراج الجني، أو يتحدث إلى الجني ويصدق ما يخبره، أو يتنقل بين التشخيصات بلا علم.","ev":["darar","ardu"]},{"t":"المتاجر بالرقية","tag":"مشبوه","cls":"bad","d":"يتخذها مهنة ابتزاز: يتهم كل مريض بالسحر أو المس، ويطلب مبالغ كبيرة، ويبيع «زيوتاً» و«مياهاً» و«أحجبة» وبرامج علاجية بلا دليل، ويجعل الزبون يعتمد عليه.","ev":["shirk","ajr"]},{"t":"العراف والمنجم والكاهن","tag":"محرّم","cls":"bad","d":"يدّعون معرفة الغيب أو المفقود أو سبب المرض بالنجوم أو الخط أو الودع أو الأرواح. وقد نهى الشرع عن إتيانهم وتصديقهم.","ev":["arraf","kahin","kuhhan","nujum"]},{"t":"الساحر والمعالج بالسحر (النشرة بسحر)","tag":"محرّم","cls":"bad","d":"يحل سحراً بسحر أو يستعين بالشياطين بكتابات وطلاسم وذبائح. جاء الوعيد في السحر والنهي عن النشرة.","ev":["mawbiqat","nushra"]},{"t":"المستعين بالجن","tag":"محرّم","cls":"bad","d":"يتخذ جنياً «خادماً» أو «مرافقاً» أو يعاهد الجن على أمر ثم يخدع الناس به. وقد بيّن القرآن أن الاستعاذة بالجن زادتهم رهقاً.","ev":["dhabh"]},{"t":"المعالج بالمحرمات","tag":"محرّم","cls":"bad","d":"يعالج بمحرم كالخمر أو النجاسة أو الدم أو الذبح لغير الله أو كتابة القرآن بنجس.","ev":["khamr","dhabh"]}]],["q",["q-jinn6","q-ghayb"]],["h",["arraf","kahin","kuhhan","nujum","nushra","khamr","dhabh","khalwa","darar"]],["sub","ثانياً: علامات الراقي الشرعي وعلامات الدجال"],["cmp",[["علامات الراقي الشرعي","ok",[["يرقي بكلام الله وبالأذكار الثابتة","ويقرأ بصوت يسمعه المريض ويفهمه، ولا يستتر بكلام غامض.",["ardu"]],["يعتقد أن الشافي هو الله","فلا يدّعي أنه يشفي بذاته ولا يضمن الشفاء ولا يعد بنتائج مؤكدة.",[]],["لا يدّعي علم الغيب","فلا يخبرك بمن سحرك أو ماذا في بيتك أو ما سيقع لك، فعلم الغيب لله.",["kahin"]],["لا يخلو بامرأة ولا يلمسها","ويرقيها بحضور محرمها وبما يحفظ العورة.",["khalwa"]],["لا يضر المريض","فلا ضرب ولا خنق ولا إهانة ولا إيذاء بدعوى إخراج الجني.",["darar"]],["أجره معتدل أو بلا أجر","ويُجيز الشرع الأجر ولا يُجيز الاستغلال.",["ajr"]],["يوجّه إلى الطبيب عند الحاجة","ولا يدعو إلى ترك العلاج الطبي أو الدواء.",["tadawaw"]]]],["علامات الدجال والمشعوذ","bad",[["يدّعي معرفة الغيب ويخبر بما لم يُخبَر به","كأن يصف بيتك وأقاربك ويسمي من سحرك، أو يطلب أشياء تخص المريض ليجعلها «دليلاً».",["arraf","kahin"]],["يكتب طلاسم وحروفاً وأرقاماً ويعطيها لتُعلَّق","وهذا من التمائم التي جاء النص بأنها شرك.",["shirk"]],["يطلب ذبحاً بصفات خاصة أو دماً أو أشياء غريبة","مما ينتهي إلى الذبح لغير الله أو تلطيخ نجس.",["dhabh"]],["يتحدث مع الجني ويصدّق ما يقوله أو يستخدمه في الإخبار","والجني لا يؤتمن، وقد يكذب ليضل.",["kuhhan"]],["يحرّم عليك الطبيب أو يزعم أن الدواء لا يفيد","وهذا مخالف لأمر النبي ﷺ بالتداوي.",["tadawaw"]],["يتهم كل مريض بالسحر أو المس ويشترط مبالغ كبيرة","ويبقيك متعلقاً به ويبيع لك «علاجاً» لا ينتهي.",["ajr"]],["يخلو بالنساء أو يلمسهن أو يطلب كشف ما لا يحل","وهذا إثم ظاهر ولا يكون من الراقي الشرعي.",["khalwa"]],["يعالج بسحر أو بما فيه استعانة بالشياطين","وهو النشرة المنهي عنها.",["nushra"]]]]]],["sub","ثالثاً: أسئلة تطرحها قبل أن تثق بمعالج"],["list","ruq-warn",[["بماذا ترقي؟","فإن قال بالقرآن والأذكار الثابتة فهو في الأصل مقبول، وإن غمض عليك أو خلط معها شيئاً فاحذر.",[]],["ماذا تطلب مني؟","ما كان من دعاء وقراءة وصبر فمقبول، وما كان من ذبح أو أشياء غريبة أو كتابة أو غيبة فاعلم أنه خارج الشرع.",["dhabh"]],["هل تضمن الشفاء؟","من ضمنه جزماً فقد ادّعى ما لا يملك. والشفاء بيد الله.",[]],["هل أراجع الطبيب؟","الجواب الصحيح نعم، ولا يغني أحدهما عن الآخر.",["tadawaw"]]]],["sub","رابعاً: إذا اشتبه عليك الأمر"],["p","اترك المعالج الذي ظهرت عليه علامة من علامات الدجل، ولا تعطه شيئاً من متعلقاتك، واستعن بنفسك بالرقية الشرعية الثابتة وراجع الطبيب، واسأل أهل العلم الموثوقين عن حكم ما طُلب منك. وإن وقع ابتزاز أو أذى فأبلغ الجهات المختصة."],["ay",[{"t":"عالم الغيب فلا يظهر على غيبه أحداً","r":[72,26,27],"n":"علم الغيب لله وحده، ولا يطلع عليه إلا من ارتضى من رسول، فمن ادعاه من الكهان والعرافين فقد كذب."},{"t":"قل لا يعلم من في السماوات والأرض الغيب إلا الله","r":[27,65],"n":"قاعدة كبرى في إبطال دعاوى الكهانة والتنجيم والاطلاع على المخبوء."}]]]},{"id":"asbab","t":"أسباب المس والسحر","d":"المس والسحر موجودان بنص القرآن والسنة، لكن لا يصح الجزم بأي منهما في كل حالة؛ فكثير من الأعراض أسبابها طبية أو نفسية. وهذا الباب يبين حقيقة كل منهما بأدلته، وأسبابه من جهة الشياطين ومن جهة الإنسان، دون تهويل ولا إنكار.","blocks":[["sub","أولاً: حقيقة المس"],["p","المس هو تسلط الشيطان أو الجني على الإنسان بالأذى، ويُعبَّر عنه بالصرع أو التخبط. وقد ذكره القرآن في آية الربا، وجاء في السنة ما يدل على وقوعه، وقرّر المفسرون ثبوته. والمراد بالمس هنا الجنس لا كل حالة."],["ay",[{"t":"الذين يأكلون الربا لا يقومون إلا كما يقوم الذي يتخبطه الشيطان من المس","r":[2,275],"n":"ذكر المس والتخبط في القرآن، واستدل بها العلماء على وقوع الصرع من الجن."},{"t":"وإما ينزغنك من الشيطان نزغ فاستعذ بالله","r":[7,200,201],"n":"علاج النزغ والطائف: الاستعاذة بالله والتذكر. وهي حال المتقي إذا مسه شيء من الشيطان."}]],["q",["q-mass"]],["h",["yajri","sara","khinzab","ayn2"]],["sub","ثانياً: أسباب المس"],["p","لا يصح تحديد سبب بعينه لكل حالة. لكن النصوص تدل على أسباب عامة تفتح باب الشيطان، وأسباب تحمي منه. وهذه الأسباب ليست جزماً في كل حال، بل هي مواطن الحذر:"],["list","ruq-warn",[["الإعراض عن ذكر الله والقرآن","قال تعالى: {ومن يعش عن ذكر الرحمن نقيض له شيطاناً فهو له قرين}. وغفلة القلب مدخل للشياطين.",["adhan"]],["المعاصي والبعد عن الطاعة","المتقي إذا مسه طائف من الشيطان تذكر واستغفر، وأما من أصرّ على الذنوب فإن الشياطين تمده في الغي.",[]],["الاستعانة بالجن وطلب خدمتهم","بيّن القرآن أن الاستعاذة بالجن زادتهم رهقاً، وهذا من أسباب التسلط وفيه شرك.",["dhabh"]],["ترك أذكار الدخول والخروج والطعام والخلاء","من ترك ذكر الله عند هذه المواضع أدرك الشيطان مبيته وعشاءه، ودخول الخلاء بلا تعوذ من مواضع الاستعاذة.",["dukhul","khubuth"]],["الغضب الشديد","الغضب من مداخل الشيطان وعلاجه التعوذ بالله منه.",["ghadab"]],["إيذاء الجن أو الاعتداء عليهم بلا إنذار","وفي السنة ما يبين أن للجن حقاً في الأمان، وقد يؤدي التعدي عليهم إلى أذى. فلا يُتسرع في قتل ما يعمر البيوت من الحيات.",["awamir"]],["العين والحسد","العين حق قد تسبب أمراضاً وأذى، وتُعالَج بالرقية والتعوذ، وليست مساً في ذاتها.",["ayn2"]]]],["q",["q-ziker","q-muttaqi","q-wasw"]],["sub","ثالثاً: حقيقة السحر"],["p","السحر حقيقة ثابتة بالقرآن والسنة، وهو من الكبائر الموبقات، ولا يضر أحداً إلا بإذن الله. وقد سُحر النبي ﷺ ولم يؤثر ذلك في الوحي ولا في التبليغ، وشفاه الله منه."],["ay",[{"t":"واتبعوا ما تتلو الشياطين على ملك سليمان","r":[2,102],"n":"ذكرت الآية السحر وتعليم الشياطين له، وأنه من أسباب التفريق بين الزوجين، وأنه لا يضر إلا بإذن الله."},{"t":"ومن شر النفاثات في العقد","r":[113,1,5],"n":"استعاذة من السحر والحسد، وفيها دلالة على أن للسحر حقيقة."},{"t":"يخيل إليه من سحرهم أنها تسعى","r":[20,66,69],"n":"سحر السحرة تخييل على الأعين، وكيدهم لا يفلح."},{"t":"ما جئتم به السحر إن الله سيبطله","r":[10,81,82],"n":"بطلان السحر وأن الله لا يصلح عمل المفسدين."}]],["q",["q-sihr-haq","q-sihr-anwa","q-falaq","q-sihr-idhn","q-kathir-sihr","q-sihr-batil","q-sahir"]],["h",["mawbiqat","suhira"]],["sub","رابعاً: أسباب السحر"],["list","ruq-warn",[["من جهة الساحر: الكفر وطاعة الشياطين","نصت الآية أن الشياطين كفروا يعلمون الناس السحر. فالساحر يتقرب إلى الشياطين بما يحبون من الشرك، وهذا أصل السحر.",["mawbiqat"]],["الحسد والحقد","سُحر النبي ﷺ بكيد من لبيد بن الأعصم، وأمرنا بالاستعاذة من شر الحاسد، وهو من أسباب السحر.",["suhira"]],["إرادة التفريق بين الناس","ومنه ما بيّنته الآية من التفريق بين المرء وزوجه، ثم اتساع الأذى إلى الأرزاق والأبدان.",[]],["اللجوء إلى السحرة والكهان لحل المشكلات","سبب لتوسع الفساد وبيع الأوهام، وفيه وعيد شديد في السنة.",["arraf","kahin"]],["من جهة المصاب: الغفلة عن الأذكار والتحصين","ما أصاب أحداً من الأذى فهو بإذن الله وقدره، ومن أسباب ضعف التحصين الغفلة عن الذكر، كما في ترك أبان بن عثمان للذكر في يوم غضب فأصابه الفالج في رواية أبي داود.",["laydurr"]]]],["sub","خامساً: الفرق بين العين والسحر والمس والوسواس والمرض"],["cards",[{"t":"العين","tag":"ثابتة","cls":"ok","d":"أثر يقع بالنظر مع الإعجاب أو الحسد، علاجه الرقية والتعوذ والدعاء بالبركة.","ev":["ayn2","jann"]},{"t":"السحر","tag":"ثابت وكبيرة","cls":"bad","d":"عمل مادي أو قولي يستعين فيه الساحر بالشياطين ليؤذي بإذن الله. علاجه الرقية الشرعية والذكر والرجوع إلى الله.","ev":["suhira","mawbiqat"]},{"t":"المس","tag":"ثابت ولا يُجزم به في كل حالة","cls":"mid","d":"تسلط جني أو شيطان على إنسان. قد يختلط بأعراض عضوية أو نفسية، فيجب التفريق بينها.","ev":["sara","yajri"]},{"t":"الوسواس","tag":"ثابت","cls":"ok","d":"خواطر يلقيها الشيطان في الصدر، وعلاجها التعوذ والإعراض والذكر.","ev":["khinzab","ghadab"]},{"t":"المرض العضوي والنفسي","tag":"يُستبعد أولاً","cls":"ok","d":"سببه طبي أو نفسي ويُعالج بالطبيب مع الرقية والدعاء والصبر. وقد أمر النبي ﷺ بالتداوي.","ev":["tadawaw"]}]],["p","نصيحة: إذا ظهرت أعراض كنوبات الإغماء أو الصرع أو الهلوسة أو القلق الشديد أو الاكتئاب فابدأ بالطبيب، مع الرقية والدعاء. ولا تتهم أحداً بالسحر أو الحسد بلا بينة، فقد قال النبي ﷺ لمن أُحيل إليه الأمر: «قد عافاني الله، فكرهت أن أثور على الناس فيه شراً»."]]},{"id":"tahsin","t":"كيفية التحصن من المس والسحر","d":"الوقاية خير من العلاج. وأساس التحصين التوحيد والتوكل على الله، ثم الأذكار الثابتة صباحاً ومساءً وعند النوم ودخول البيت والخروج منه، مع المحافظة على الصلاة وقراءة القرآن وترك المعاصي. وكل ما هنا بنص ثابت.","blocks":[["sub","أولاً: الأساس: التوحيد والتوكل على الله"],["p","لا يضر أحداً شيء إلا بإذن الله. فمن عرف ذلك وتوكل على الله اطمأن قلبه وسقط خوفه من السحر والجن. والتوكل لا يعني ترك الأسباب بل فعلها مع تعلق القلب بالله."],["ay",[{"t":"ومن يتوكل على الله فهو حسبه","r":[65,2,3],"n":"التوكل مع التقوى يكفي العبد أمره."},{"t":"قل لن يصيبنا إلا ما كتب الله لنا","r":[9,51],"n":"لا يصيب أحداً شيء إلا بقدر الله، وعلى الله فليتوكل المؤمنون."},{"t":"وليس بضارهم شيئا إلا بإذن الله","r":[58,10],"n":"الأذى لا يقع إلا بإذن الله، فلا يُخاف غيره."}]],["q",["q-tawakkul","q-yadurr"]],["sub","ثانياً: أذكار الصباح والمساء"],["p","من أعظم ما يحفظ الإنسان من الشيطان وأذاه أذكار الصباح والمساء. وقد جمعنا أعظمها دلالةً على التحصين، وللتوسع في الأذكار كلها راجع باب «أذكار الصباح والمساء»."],["links",[["adhkar","أذكار الصباح والمساء كاملة بمصادرها"]]],["h",["laydurr","takfik","hirz"]],["sub","ثالثاً: التحصين عند النوم"],["list","ruq-steps",[["الإخلاص والمعوذتان مع النفث والمسح","قراءتها ثلاثاً بعد جمع الكفين والنفث فيهما، ثم المسح على الجسد.",["nawm"]],["آية الكرسي","لا يزال عليه من الله حافظ ولا يقربه شيطان حتى يصبح.",["kursi"]],["خواتيم البقرة","تكفيانه.",["baqara"]]]],["sub","رابعاً: تحصين البيت"],["list","ruq-steps",[["قراءة سورة البقرة","الشيطان ينفر من البيت الذي تُقرأ فيه سورة البقرة، وفي الآيتين الأخيرتين منها ما يحمي الدار ثلاث ليال.",["buyut","baqara3"]],["ذكر الله عند دخول البيت والطعام","فيُحرم الشيطان المبيت والعشاء.",["dukhul"]],["إغلاق الأبواب وذكر اسم الله عند المساء","وإطفاء السراج وتغطية الأواني.",["jinh"]],["صلاة النافلة وقراءة القرآن في البيت","ولا يُجعل البيت كالمقبرة.",["sakan"]],["الأذان وإقامة الصلاة","فيفر منه الشيطان، والمحافظة على الجماعة من أسباب الحفظ.",["adhan"]],["الدعاء عند الإتيان للأهل","ففيه حفظ الذرية.",["jinab"]]]],["sub","خامساً: تحصين النفس عند الخروج والنزول والغضب والخلاء"],["list","ruq-steps",[["عند الخروج من البيت","«بسم الله توكلت على الله ولا حول ولا قوة إلا بالله».",["kharaj"]],["عند النزول في مكان","«أعوذ بكلمات الله التامات من شر ما خلق».",["nuzul"]],["عند الغضب","«أعوذ بالله من الشيطان الرجيم».",["ghadab"]],["عند دخول الخلاء","«اللهم إني أعوذ بك من الخبث والخبائث».",["khubuth"]],["عند الوسوسة في الصلاة","التعوذ والتفل عن اليسار ثلاثاً.",["khinzab"]]]],["sub","سادساً: تحصين الأولاد"],["p","من هدي النبي ﷺ تعويذ الأولاد بكلمات الله التامة من كل شيطان وهامة وعين لامة، وإبقاؤهم في البيت عند دخول الليل."],["links",[["taarif","حديث «أعيذكما بكلمات الله التامة» في باب التعريف"]]],["sub","سابعاً: جدول الوقاية اليومية"],["list","ruq-rules",[["الصباح والمساء","بسم الله الذي لا يضر مع اسمه شيء، والإخلاص والمعوذتان ثلاثاً، وأعوذ بكلمات الله التامات، والتهليل مئة مرة.",["laydurr","takfik","hirz"]],["قبل النوم","الإخلاص والمعوذتان بالنفث والمسح، وآية الكرسي، وخواتيم البقرة.",["nawm","kursi","baqara"]],["عند الخروج من البيت ودخوله","البسملة والتوكل، وذكر الله عند الدخول.",["kharaj","dukhul"]],["عند المساء","إغلاق الأبواب وذكر الله وكفّ الصبيان.",["jinh"]],["عند الغضب والخلاء والوسوسة","التعوذ بالله من الشيطان.",["ghadab","khubuth","khinzab"]],["طوال اليوم","المحافظة على الصلوات والجماعة وقراءة القرآن وترك المعاصي.",["adhan","sakan"]]]],["h",["dukhul","jinh","kharaj","nuzul","ghadab","jinab","khubuth","sakan","adhan","awamir","baqara3"]],["sub","ثامناً: ما لا يصح في التحصين"],["list","ruq-warn",[["التمائم والحروز والخرزات","تعليقها لدفع الأذى أو الحسد شرك لا حماية، وقد قال ﷺ: «إن الرقى والتمائم والتولة شرك».",["shirk"]],["الذهاب إلى السحرة والكهان","للتحصين أو لحل مشكلة: محرّم ومن أسباب زيادة البلاء.",["arraf","kahin"]],["حل السحر بسحر مثله","وهو النشرة المنهي عنها.",["nushra"]],["الاعتماد على الرقية وترك الطبيب","والتداوي مأمور به.",["tadawaw"]]]],["sub","تاسعاً: إذا أصابك شيء"],["p","اصبر واحتسب، وارق نفسك بالأذكار والمعوذات، وراجع الطبيب إن كان الأمر عضوياً أو نفسياً، واستعن براقٍ شرعي ضابط عند الحاجة وفق المعايير المذكورة في باب «أنواع المعالجين»، وأكثر من الاستغفار والدعاء. وفي قصة المرأة التي كانت تُصرع أن الصبر على البلاء ثوابه الجنة."],["links",[["muaalij","أنواع المعالجين ومعايير التمييز بينهم"],["kayf","كيف يرقي المسلم نفسه وأهله"]]]]},{"id":"asl","t":"القرآن شفاء: آيات الشفاء","d":"وصف الله كتابه بأنه شفاء في ستة مواضع، يجمعها المصنفون في الرقية تحت اسم «آيات الشفاء». والشفاء فيها يعم شفاء القلوب من الشك والهوى، ويشمل عند جمهور المفسرين شفاء الأبدان بالرقية والتعوذ. وليس في تخصيص هذه الآيات بعدد أو هيئة نص مرفوع، وإنما جُمعت لاشتراكها في لفظ الشفاء.","en_t":"The Quran is healing: the verses of healing","en_d":"Allah describes His Book as healing in six places, which authors on ruqyah gather under the name \"the verses of healing\". Healing in them covers the healing of hearts from doubt and desire, and, according to most exegetes, includes healing of bodies through ruqyah and seeking refuge. No authentic text from the Prophet fixes these verses to a number or a manner; they are grouped only because they share the word \"healing\".","ay":[{"t":"وننزل من القرآن ما هو شفاء ورحمة","r":[17,82],"n":"أصرح آية في الباب، وفيها اختلف العلماء: أهو شفاء للقلوب وحدها أم للأبدان أيضاً بالرقى، كما في أقوال العلماء أدناه.","en_t":"We send down of the Quran that which is healing and mercy","en_n":"The clearest verse on the subject. Scholars differed whether it is healing for hearts only or for bodies too through ruqyah, as quoted in the scholars' statements below."},{"t":"وشفاء لما في الصدور","r":[10,57],"n":"الموعظة والشفاء والهدى والرحمة أوصاف أربعة للقرآن، والشفاء هنا لأمراض الشبهات والشهوات.","en_t":"And healing for what is in the breasts","en_n":"Admonition, healing, guidance and mercy are four descriptions of the Quran; healing here is for the diseases of doubts and desires."},{"t":"قل هو للذين آمنوا هدى وشفاء","r":[41,44],"n":"الانتفاع بالقرآن شفاءً مشروط بالإيمان به، فمن أعرض عنه لم ينتفع به.","en_t":"Say: it is guidance and healing for those who believe","en_n":"Benefiting from the Quran as healing depends on believing in it; whoever turns away from it does not benefit."},{"t":"ويشف صدور قوم مؤمنين","r":[9,14],"n":"شفاء الصدور من الغيظ والكرب بنصر الله، وهو من آيات الشفاء التي يذكرها أهل الرقية.","en_t":"And heal the breasts of a believing people","en_n":"Healing of the breasts from anger and distress through the victory of Allah; it is among the verses of healing cited by those who practise ruqyah."},{"t":"يخرج من بطونها شراب مختلف ألوانه فيه شفاء للناس","r":[16,69],"n":"آية العسل، وهي أصل في مشروعية التداوي بالأسباب الحسية مع الرقية، وقد صدّقها النبي ﷺ في حديث العسل.","en_t":"There emerges from their bellies a drink of varying colours, in which there is healing for people","en_n":"The verse of honey: a basis for using physical remedies alongside ruqyah, and the Prophet ﷺ affirmed it in the hadith of honey."},{"t":"وإذا مرضت فهو يشفين","r":[26,80],"n":"قول إبراهيم عليه السلام: نسب المرض إلى نفسه أدباً مع الله، ونسب الشفاء إلى ربه، فالشافي هو الله وحده.","en_t":"And when I am ill, it is He who heals me","en_n":"The words of Ibrahim, peace be upon him: he attributed illness to himself out of courtesy towards Allah and attributed healing to his Lord, for Allah alone is the Healer."}]},{"id":"ruqa","t":"ما يُرقى به من سور القرآن وآياته","d":"القرآن كله يُرقى به، وقد ثبت في السنة تخصيص سور وآيات بالرقية والتحصين: الفاتحة، والمعوذات، وآية الكرسي، وخواتيم سورة البقرة. وذكر أهل العلم آيات في إبطال السحر لموافقة معناها، دون نص مرفوع في تعيينها.","en_t":"The surahs and verses used for ruqyah","en_d":"The whole Quran may be recited as ruqyah, and the Sunnah singles out certain surahs and verses for ruqyah and protection: al-Fatihah, the three surahs of refuge, Ayat al-Kursi and the closing verses of al-Baqarah. Scholars also mention verses about the undoing of magic because of their meaning, without an authentic text from the Prophet specifying them.","ay":[{"t":"سورة الفاتحة","r":[1,1,7],"n":"رقى بها أحد الصحابة سيدَ قوم لُدغ فبرأ، فأقرّه النبي ﷺ وقال: «وما يدريك أنها رقية». انظر الحديث في الباب التالي.","en_t":"Surat al-Fatihah","en_n":"A Companion recited it as ruqyah over a tribal chief who had been stung, and he recovered; the Prophet ﷺ approved and said: \"How did you know it is a ruqyah?\" See the hadith in the next chapter.","h":"fatiha"},{"t":"آية الكرسي","r":[2,255],"n":"من قرأها إذا أوى إلى فراشه لم يزل عليه من الله حافظ، كما في حديث أبي هريرة عند البخاري.","en_t":"Ayat al-Kursi (the Verse of the Throne)","en_n":"Whoever recites it on going to bed remains under a guardian from Allah, as in the hadith of Abu Hurayrah in al-Bukhari.","h":"kursi"},{"t":"خواتيم سورة البقرة","r":[2,285,286],"n":"من قرأ بالآيتين من آخر سورة البقرة في ليلة كفتاه، والشيطان ينفر من البيت الذي تقرأ فيه سورة البقرة.","en_t":"The closing verses of al-Baqarah","en_n":"Whoever recites the last two verses of al-Baqarah at night, they suffice him; and Satan flees from the house in which al-Baqarah is recited.","h":"baqara"},{"t":"سورة الإخلاص","r":[112,1,4],"n":"كان النبي ﷺ يجمعها مع المعوذتين فينفث في كفيه ويمسح بهما جسده كل ليلة.","en_t":"Surat al-Ikhlas","en_n":"The Prophet ﷺ used to recite it with the two surahs of refuge, blow lightly into his palms and wipe his body with them every night.","h":"nawm"},{"t":"سورة الفلق","r":[113,1,5],"n":"استعاذة من شر الخلق عامة، ومن السحر والحسد خاصة، ويدخل في الحاسد العائن.","en_t":"Surat al-Falaq","en_n":"Seeking refuge from the evil of creation in general, and from magic and envy in particular; the one who casts the evil eye is included in \"the envier\".","h":"muawwidhat"},{"t":"سورة الناس","r":[114,1,6],"n":"استعاذة بربوبية الله وملكه وألوهيته من شر الوسواس الخناس من الجن والناس.","en_t":"Surat al-Nas","en_n":"Seeking refuge in the Lordship, Sovereignty and Divinity of Allah from the evil of the retreating whisperer, among jinn and mankind.","h":"muawwidhat"},{"t":"آيات إبطال السحر في قصة موسى","r":[10,81,82],"n":"«إن الله سيبطله»: يذكرها أهل العلم في الرقية من السحر مع آيات الأعراف وطه في القصة نفسها، لموافقة معناها، وليس في تعيينها نص مرفوع.","en_t":"The verses on undoing magic in the story of Musa","en_n":"\"Allah will surely nullify it\": scholars cite these, with the verses of al-A'raf and Ta-Ha from the same story, in ruqyah against magic because of their meaning; no authentic text from the Prophet specifies them."}]},{"id":"sunna","t":"الرقية في السنة الصحيحة","d":"أحاديث صحيحة في الرقية بالقرآن والأدعية النبوية، كل حديث بنصه من الكتب المضمّنة في مشكاة، وتخريجه برقمه، ودرجته.","en_t":"Ruqyah in the authentic Sunnah","en_d":"Authentic hadiths on ruqyah with the Quran and with the Prophet's supplications, each quoted from the books bundled in Mishkat, with its reference number and grade."},{"id":"tadawi","t":"التداوي والأخذ بالأسباب","d":"الرقية لا تعارض الطب؛ فقد أمر النبي ﷺ بالتداوي، وأخبر أن لكل داء دواء، ووصف العسل لمن اشتكى بطنه. والجمع بين الرقية والعلاج هو هدي السنة.","en_t":"Seeking treatment and taking the means","en_d":"Ruqyah does not oppose medicine. The Prophet ﷺ commanded seeking treatment, told that every disease has a cure, and prescribed honey for one whose stomach was ailing. Combining ruqyah with treatment is the way of the Sunnah."},{"id":"ulama","t":"أقوال العلماء بمصادرها","d":"نقول بلفظها من كتب التفسير المضمّنة في مشكاة، ونقلان من كتابين غير مضمّنين، مع بيان موضع كل نقل.","en_t":"Statements of scholars with their sources","en_d":"Verbatim quotations from the tafsir books bundled in Mishkat, and two quotations from books not bundled, with the location of each."},{"id":"dawabit","t":"ضوابط الرقية المشروعة","d":"شروط تجعل الرقية مشروعة، مستخلصة من النصوص وما قرره أهل العلم.","en_t":"The conditions of lawful ruqyah","en_d":"Conditions that make ruqyah lawful, drawn from the texts and from what scholars have established."},{"id":"kayf","t":"كيف يرقي المسلم نفسه وأهله","d":"خطوات عملية مأخوذة من هدي النبي ﷺ، لا تحتاج إلى وسيط.","en_t":"How a Muslim performs ruqyah for himself and his family","en_d":"Practical steps taken from the guidance of the Prophet ﷺ, needing no intermediary."},{"id":"mahadhir","t":"محاذير وأخطاء شائعة","d":"ما يجب الحذر منه في باب الرقية، وحديث مشهور لا يصح رفعه.","en_t":"Cautions and common mistakes","en_d":"What must be avoided in ruqyah, and a well-known hadith whose attribution to the Prophet is not authentic."}],"h":[{"id":"fatiha","t":"الرقية بفاتحة الكتاب","x":"عَنْ أَبِي سَعِيدٍ، أَنَّ رَهْطًا، مِنْ أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم انْطَلَقُوا فِي سَفْرَةٍ سَافَرُوهَا، حَتَّى نَزَلُوا بِحَىٍّ مِنْ أَحْيَاءِ الْعَرَبِ فَاسْتَضَافُوهُمْ، فَأَبَوْا أَنْ يُضَيِّفُوهُمْ، فَلُدِغَ سَيِّدُ ذَلِكَ الْحَىِّ، فَسَعَوْا لَهُ بِكُلِّ شَىْءٍ لاَ يَنْفَعُهُ شَىْءٌ، فَقَالَ بَعْضُهُمْ لَوْ أَتَيْتُمْ هَؤُلاَءِ الرَّهْطَ الَّذِينَ قَدْ نَزَلُوا بِكُمْ، لَعَلَّهُ أَنْ يَكُونَ عِنْدَ بَعْضِهِمْ شَىْءٌ. فَأَتَوْهُمْ فَقَالُوا يَا أَيُّهَا الرَّهْطُ إِنَّ سَيِّدَنَا لُدِغَ، فَسَعَيْنَا لَهُ بِكُلِّ شَىْءٍ، لاَ يَنْفَعُهُ شَىْءٌ، فَهَلْ عِنْدَ أَحَدٍ مِنْكُمْ شَىْءٌ فَقَالَ بَعْضُهُمْ نَعَمْ، وَاللَّهِ إِنِّي لَرَاقٍ، وَلَكِنْ وَاللَّهِ لَقَدِ اسْتَضَفْنَاكُمْ فَلَمْ تُضَيِّفُونَا، فَمَا أَنَا بِرَاقٍ لَكُمْ حَتَّى تَجْعَلُوا لَنَا جُعْلاً. فَصَالَحُوهُمْ عَلَى قَطِيعٍ مِنَ الْغَنَمِ، فَانْطَلَقَ فَجَعَلَ يَتْفُلُ وَيَقْرَأُ {الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ} حَتَّى لَكَأَنَّمَا نُشِطَ مِنْ عِقَالٍ، فَانْطَلَقَ يَمْشِي مَا بِهِ قَلَبَةٌ. قَالَ فَأَوْفَوْهُمْ جُعْلَهُمُ الَّذِي صَالَحُوهُمْ عَلَيْهِ، فَقَالَ بَعْضُهُمُ اقْسِمُوا. فَقَالَ الَّذِي رَقَى لاَ تَفْعَلُوا حَتَّى نَأْتِيَ رَسُولَ اللَّهِ صلى الله عليه وسلم فَنَذْكُرَ لَهُ الَّذِي كَانَ، فَنَنْظُرَ مَا يَأْمُرُنَا. فَقَدِمُوا عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَذَكَرُوا لَهُ فَقَالَ \" وَمَا يُدْرِيكَ أَنَّهَا رُقْيَةٌ أَصَبْتُمُ اقْسِمُوا وَاضْرِبُوا لِي مَعَكُمْ بِسَهْمٍ \".","src":[["bukhari","5749"],["muslim","2201"]],"gr":"صحيح: متفق عليه","dg":"","f":"فيه مشروعية الرقية بالقرآن، وأن الفاتحة رقية، وجواز أخذ الأجرة على الرقية إذا نفعت.","en":"Abu Sa'id reported that a group of the Prophet's Companions stopped at an Arab tribe that refused them hospitality. The chief was stung, and nothing helped him. One of the Companions recited al-Fatihah over him, blowing lightly, and he rose as if released from a tether. When they told the Prophet ﷺ, he said: \"How did you know it is a ruqyah? You have done right; divide it and give me a share with you.\"","ch":"sunna"},{"id":"muawwidhat","t":"النفث بالمعوذات عند المرض","x":"عَنْ عَائِشَةَ، رضى الله عنها أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم كَانَ إِذَا اشْتَكَى يَقْرَأُ عَلَى نَفْسِهِ بِالْمُعَوِّذَاتِ وَيَنْفُثُ، فَلَمَّا اشْتَدَّ وَجَعُهُ كُنْتُ أَقْرَأُ عَلَيْهِ وَأَمْسَحُ بِيَدِهِ رَجَاءَ بَرَكَتِهَا.","src":[["bukhari","5016"],["muslim","2192"]],"gr":"صحيح: متفق عليه","dg":"","f":"يرقي المريض نفسه بالمعوذات وينفث، ويجوز أن يرقيه غيره ويمسح عليه.","en":"'A'ishah reported that when the Messenger of Allah ﷺ was ill, he would recite the surahs of refuge over himself and blow lightly. When his pain grew severe, she would recite over him and wipe him with his own hand, hoping for its blessing.","ch":"sunna"},{"id":"nawm","t":"التحصين بالإخلاص والمعوذتين قبل النوم","x":"عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ إِذَا أَوَى إِلَى فِرَاشِهِ كُلَّ لَيْلَةٍ جَمَعَ كَفَّيْهِ ثُمَّ نَفَثَ فِيهِمَا فَقَرَأَ فِيهِمَا {قُلْ هُوَ اللَّهُ أَحَدٌ} وَ{قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ} وَ{قُلْ أَعُوذُ بِرَبِّ النَّاسِ} ثُمَّ يَمْسَحُ بِهِمَا مَا اسْتَطَاعَ مِنْ جَسَدِهِ يَبْدَأُ بِهِمَا عَلَى رَأْسِهِ وَوَجْهِهِ وَمَا أَقْبَلَ مِنْ جَسَدِهِ يَفْعَلُ ذَلِكَ ثَلاَثَ مَرَّاتٍ.","src":[["bukhari","5017"]],"gr":"صحيح","dg":"","f":"هيئة الرقية: جمع الكفين، والنفث فيهما، والقراءة، ثم المسح على ما استطاع من الجسد، ثلاث مرات.","en":"'A'ishah reported that every night, when the Prophet ﷺ went to bed, he would put his palms together, blow lightly into them and recite into them \"Say: He is Allah, One\", \"Say: I seek refuge in the Lord of daybreak\" and \"Say: I seek refuge in the Lord of mankind\", then wipe as much of his body as he could, starting with his head, face and the front of his body, doing so three times.","ch":"sunna"},{"id":"jibril","t":"رقية جبريل للنبي ﷺ","x":"عَنْ أَبِي سَعِيدٍ، أَنَّ جِبْرِيلَ، أَتَى النَّبِيَّ صلى الله عليه وسلم فَقَالَ يَا مُحَمَّدُ اشْتَكَيْتَ فَقَالَ  \" نَعَمْ \" . قَالَ بِاسْمِ اللَّهِ أَرْقِيكَ مِنْ كُلِّ شَىْءٍ يُؤْذِيكَ مِنْ شَرِّ كُلِّ نَفْسٍ أَوْ عَيْنِ حَاسِدٍ اللَّهُ يَشْفِيكَ بِاسْمِ اللَّهِ أَرْقِيكَ .","src":[["muslim","2186"]],"gr":"صحيح","dg":"","f":"الرقية بذكر اسم الله والدعاء بالشفاء، وفيه أن العين والحسد مما يُرقى منه.","en":"Abu Sa'id reported that Jibril came to the Prophet ﷺ and said: \"O Muhammad, are you unwell?\" He said: \"Yes.\" Jibril said: \"In the name of Allah I perform ruqyah for you, from everything that harms you, from the evil of every soul or envious eye. May Allah heal you. In the name of Allah I perform ruqyah for you.\"","ch":"sunna"},{"id":"adhhib","t":"«اللهم رب الناس أذهب الباس»","x":"عَنْ عَائِشَةَ ـ رضى الله عنها ـ أَنَّ النَّبِيَّ صلى الله عليه وسلم كَانَ يُعَوِّذُ بَعْضَ أَهْلِهِ، يَمْسَحُ بِيَدِهِ الْيُمْنَى وَيَقُولُ  \" اللَّهُمَّ رَبَّ النَّاسِ أَذْهِبِ الْبَاسَ، اشْفِهِ وَأَنْتَ الشَّافِي، لاَ شِفَاءَ إِلاَّ شِفَاؤُكَ، شِفَاءً لاَ يُغَادِرُ سَقَمًا \"","src":[["bukhari","5743"],["muslim","2191"]],"gr":"صحيح: متفق عليه","dg":"","f":"من أجمع الأدعية النبوية للمريض، يقال مع المسح باليد اليمنى.","en":"'A'ishah reported that the Prophet ﷺ used to seek protection for some of his family, wiping with his right hand and saying: \"O Allah, Lord of mankind, remove the harm. Heal him, for You are the Healer; there is no healing but Your healing, a healing that leaves no illness behind.\"","ch":"sunna"},{"id":"yad","t":"وضع اليد على موضع الألم","x":"عَنْ عُثْمَانَ بْنِ أَبِي الْعَاصِ الثَّقَفِيِّ، أَنَّهُ شَكَا إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم وَجَعًا يَجِدُهُ فِي جَسَدِهِ مُنْذُ أَسْلَمَ . فَقَالَ لَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم  \" ضَعْ يَدَكَ عَلَى الَّذِي تَأَلَّمَ مِنْ جَسَدِكَ وَقُلْ بِاسْمِ اللَّهِ . ثَلاَثًا . وَقُلْ سَبْعَ مَرَّاتٍ أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ \" .","src":[["muslim","2202"]],"gr":"صحيح","dg":"","f":"يرقي المريض نفسه بيده على موضع الألم: «بسم الله» ثلاثاً، ثم الاستعاذة سبعاً.","en":"'Uthman ibn Abi al-'As complained to the Messenger of Allah ﷺ of a pain he had felt in his body since accepting Islam. The Messenger of Allah ﷺ said: \"Place your hand on the part of your body that hurts and say 'In the name of Allah' three times, and say seven times: I seek refuge in Allah and His power from the evil of what I feel and what I fear.\"","ch":"sunna"},{"id":"ardu","t":"«لا بأس بالرقى ما لم يكن فيه شرك»","x":"عَنْ عَوْفِ بْنِ مَالِكٍ الأَشْجَعِيِّ، قَالَ كُنَّا نَرْقِي فِي الْجَاهِلِيَّةِ فَقُلْنَا يَا رَسُولَ اللَّهِ كَيْفَ تَرَى فِي ذَلِكَ فَقَالَ  \" اعْرِضُوا عَلَىَّ رُقَاكُمْ لاَ بَأْسَ بِالرُّقَى مَا لَمْ يَكُنْ فِيهِ شِرْكٌ \" .","src":[["muslim","2200"]],"gr":"صحيح","dg":"","f":"الأصل الجامع في الباب: كل رقية خلت من الشرك جائزة، والمرجع في معرفة ذلك إلى الشرع.","en":"'Awf ibn Malik al-Ashja'i said: \"We used to perform ruqyah in the Days of Ignorance, so we said: O Messenger of Allah, what do you think of that? He said: Present your ruqyahs to me. There is no harm in ruqyah as long as it contains no shirk.\"","ch":"sunna"},{"id":"yanfa","t":"«من استطاع منكم أن ينفع أخاه فلينفعه»","x":"عَنْ جَابِرٍ، قَالَ نَهَى رَسُولُ اللَّهِ صلى الله عليه وسلم عَنِ الرُّقَى فَجَاءَ آلُ عَمْرِو بْنِ حَزْمٍ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّهُ كَانَتْ عِنْدَنَا رُقْيَةٌ نَرْقِي بِهَا مِنَ الْعَقْرَبِ وَإِنَّكَ نَهَيْتَ عَنِ الرُّقَى . قَالَ فَعَرَضُوهَا عَلَيْهِ . فَقَالَ  \" مَا أَرَى بَأْسًا مَنِ اسْتَطَاعَ مِنْكُمْ أَنْ يَنْفَعَ أَخَاهُ فَلْيَنْفَعْهُ \" .","src":[["muslim","2199"]],"gr":"صحيح","dg":"","f":"النهي الأول كان عن رقى الجاهلية، ثم أذن النبي ﷺ فيما خلا من المحذور، ورغّب في نفع المسلم أخاه.","en":"Jabir said: The Messenger of Allah ﷺ forbade ruqyah. Then the family of 'Amr ibn Hazm came and said: \"O Messenger of Allah, we had a ruqyah we used for scorpion stings, and you have forbidden ruqyah.\" They presented it to him, and he said: \"I see no harm in it. Whoever among you is able to benefit his brother, let him do so.\"","ch":"sunna"},{"id":"ayn","t":"الاسترقاء من العين","x":"عَنْ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ أَمَرَنِي رَسُولُ اللَّهِ صلى الله عليه وسلم أَوْ أَمَرَ أَنْ يُسْتَرْقَى مِنَ الْعَيْنِ.","src":[["bukhari","5738"],["bukhari","5740"],["muslim","2187"]],"gr":"صحيح","dg":"","f":"العين حق كما في الحديث المتفق عليه، ويشرع الاسترقاء منها.","en":"'A'ishah said: \"The Messenger of Allah ﷺ commanded me, or commanded, that ruqyah be sought against the evil eye.\"","ch":"sunna"},{"id":"rukhsa","t":"الرخصة في الرقية من العين والحمة والنملة","x":"عَنْ أَنَسٍ، قَالَ رَخَّصَ رَسُولُ اللَّهِ صلى الله عليه وسلم فِي الرُّقْيَةِ مِنَ الْعَيْنِ وَالْحُمَةِ وَالنَّمْلَةِ","src":[["muslim","2196"]],"gr":"صحيح","dg":"","f":"الحُمة: سم ذوات السموم كالعقرب، والنملة: قروح تخرج في الجنب. وذِكرها لا يحصر الرقية فيها.","en":"Anas said: \"The Messenger of Allah ﷺ permitted ruqyah against the evil eye, venomous stings and namlah (sores that break out on the side).\"","ch":"sunna"},{"id":"kursi","t":"آية الكرسي حفظ من الشيطان","x":"… قَالَ دَعْنِي أُعَلِّمْكَ كَلِمَاتٍ يَنْفَعُكَ اللَّهُ بِهَا. قُلْتُ مَا هُوَ قَالَ إِذَا أَوَيْتَ إِلَى فِرَاشِكَ فَاقْرَأْ آيَةَ الْكُرْسِيِّ {اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَىُّ الْقَيُّومُ} حَتَّى تَخْتِمَ الآيَةَ، فَإِنَّكَ لَنْ يَزَالَ عَلَيْكَ مِنَ اللَّهِ حَافِظٌ وَلاَ يَقْرَبَنَّكَ شَيْطَانٌ حَتَّى تُصْبِحَ. فَخَلَّيْتُ سَبِيلَهُ فَأَصْبَحْتُ، فَقَالَ لِي رَسُولُ اللَّهِ صلى الله عليه وسلم \" مَا فَعَلَ أَسِيرُكَ الْبَارِحَةَ \". قُلْتُ يَا رَسُولَ اللَّهِ زَعَمَ أَنَّهُ يُعَلِّمُنِي كَلِمَاتٍ، يَنْفَعُنِي اللَّهُ بِهَا، فَخَلَّيْتُ سَبِيلَهُ. قَالَ \" مَا هِيَ \". قُلْتُ قَالَ لِي إِذَا أَوَيْتَ إِلَى فِرَاشِكَ فَاقْرَأْ آيَةَ الْكُرْسِيِّ مِنْ أَوَّلِهَا حَتَّى تَخْتِمَ {اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَىُّ الْقَيُّومُ} وَقَالَ لِي لَنْ يَزَالَ عَلَيْكَ مِنَ اللَّهِ حَافِظٌ وَلاَ يَقْرَبَكَ شَيْطَانٌ حَتَّى تُصْبِحَ، وَكَانُوا أَحْرَصَ شَىْءٍ عَلَى الْخَيْرِ. فَقَالَ النَّبِيُّ صلى الله عليه وسلم \" أَمَا إِنَّهُ قَدْ صَدَقَكَ وَهُوَ كَذُوبٌ، تَعْلَمُ مَنْ تُخَاطِبُ مُنْذُ ثَلاَثِ لَيَالٍ يَا أَبَا هُرَيْرَةَ \". قَالَ لاَ. قَالَ \" ذَاكَ شَيْطَانٌ \".","src":[["bukhari","2311"]],"gr":"صحيح، رواه البخاري معلقاً بصيغة الجزم","dg":"","f":"قراءة آية الكرسي عند النوم سبب للحفظ من الشيطان حتى الصباح، وقد أقرّ النبي ﷺ ذلك.","en":"From the hadith of Abu Hurayrah, who was guarding the zakat of Ramadan: the thief said, \"Let me teach you words by which Allah will benefit you: when you go to bed, recite Ayat al-Kursi to its end, and you will remain under a guardian from Allah, and no devil will come near you until morning.\" The Prophet ﷺ said: \"He told you the truth, though he is a liar... That was a devil.\"","ch":"sunna"},{"id":"baqara","t":"خواتيم البقرة تكفي قارئها","x":"عَنْ أَبِي مَسْعُودٍ ـ رضى الله عنه ـ قَالَ قَالَ النَّبِيُّ صلى الله عليه وسلم  \" مَنْ قَرَأَ بِالآيَتَيْنِ مِنْ آخِرِ سُورَةِ الْبَقَرَةِ فِي لَيْلَةٍ كَفَتَاهُ\".","src":[["bukhari","5009"],["muslim","807"]],"gr":"صحيح: متفق عليه","dg":"","f":"قيل: كفتاه من قيام الليل، وقيل: من كل سوء، وكلا المعنيين صحيح عند جمع من الشراح.","en":"Abu Mas'ud reported that the Prophet ﷺ said: \"Whoever recites the two verses at the end of Surat al-Baqarah at night, they will suffice him.\"","ch":"sunna"},{"id":"buyut","t":"الشيطان ينفر من بيت تقرأ فيه البقرة","x":"عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ  \" لاَ تَجْعَلُوا بُيُوتَكُمْ مَقَابِرَ إِنَّ الشَّيْطَانَ يَنْفِرُ مِنَ الْبَيْتِ الَّذِي تُقْرَأُ فِيهِ سُورَةُ الْبَقَرَةِ \" .","src":[["muslim","780"]],"gr":"صحيح","dg":"","f":"تحصين البيوت بتلاوة القرآن، وسورة البقرة خاصة.","en":"Abu Hurayrah reported that the Messenger of Allah ﷺ said: \"Do not make your houses graves. Satan flees from the house in which Surat al-Baqarah is recited.\"","ch":"sunna"},{"id":"shifaa","t":"«ما أنزل الله داء إلا أنزل له شفاء»","x":"عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ  \" مَا أَنْزَلَ اللَّهُ دَاءً إِلاَّ أَنْزَلَ لَهُ شِفَاءً \".","src":[["bukhari","5678"]],"gr":"صحيح","dg":"","f":"فيه تقوية لنفس المريض ورجاؤه، وحثّ على طلب الدواء والبحث عنه.","en":"Abu Hurayrah reported that the Prophet ﷺ said: \"Allah has not sent down any disease without sending down a cure for it.\"","ch":"tadawi"},{"id":"dawa","t":"«لكل داء دواء»","x":"عَنْ جَابِرٍ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم أَنَّهُ قَالَ  \" لِكُلِّ دَاءٍ دَوَاءٌ فَإِذَا أُصِيبَ دَوَاءُ الدَّاءِ بَرَأَ بِإِذْنِ اللَّهِ عَزَّ وَجَلَّ \" .","src":[["muslim","2204"]],"gr":"صحيح","dg":"","f":"الشفاء بإذن الله عند إصابة الدواء المناسب، وهذا أصل في تشخيص الداء على وجهه.","en":"Jabir reported that the Messenger of Allah ﷺ said: \"Every disease has a cure. When the cure matches the disease, it is healed by the permission of Allah, Mighty and Majestic.\"","ch":"tadawi"},{"id":"tadawaw","t":"«تداووا عباد الله»","x":"عَنْ أُسَامَةَ بْنِ شَرِيكٍ، قَالَ أَتَيْتُ النَّبِيَّ صلى الله عليه وسلم وَأَصْحَابُهُ كَأَنَّمَا عَلَى رُءُوسِهِمُ الطَّيْرُ فَسَلَّمْتُ ثُمَّ قَعَدْتُ فَجَاءَ الأَعْرَابُ مِنْ هَا هُنَا وَهَا هُنَا فَقَالُوا يَا رَسُولَ اللَّهِ أَنَتَدَاوَى فَقَالَ  \" تَدَاوَوْا فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَمْ يَضَعْ دَاءً إِلاَّ وَضَعَ لَهُ دَوَاءً غَيْرَ دَاءٍ وَاحِدٍ الْهَرَمُ \" .","src":[["abudawud","3855"],["tirmidhi","2038"]],"gr":"","dg":"الألباني: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: إسناده صحيح","f":"أمر صريح بالتداوي، فطلب العلاج من الأخذ بالأسباب المأمور به، ولا ينافي التوكل.","en":"Usamah ibn Sharik said: I came to the Prophet ﷺ while his Companions sat as if birds were on their heads. Bedouins came from here and there and said: \"O Messenger of Allah, shall we seek treatment?\" He said: \"Seek treatment, for Allah, Mighty and Majestic, has not placed a disease without placing a cure for it, except one disease: old age.\"","ch":"tadawi"},{"id":"asal","t":"«صدق الله وكذب بطن أخيك»","x":"عَنْ أَبِي سَعِيدٍ، أَنَّ رَجُلاً، أَتَى النَّبِيَّ صلى الله عليه وسلم فَقَالَ أَخِي يَشْتَكِي بَطْنَهُ. فَقَالَ \" اسْقِهِ عَسَلاً \". ثُمَّ أَتَى الثَّانِيَةَ فَقَالَ \" اسْقِهِ عَسَلاً \". ثُمَّ أَتَاهُ فَقَالَ فَعَلْتُ. فَقَالَ \" صَدَقَ اللَّهُ، وَكَذَبَ بَطْنُ أَخِيكَ، اسْقِهِ عَسَلاً \". فَسَقَاهُ فَبَرَأَ.","src":[["bukhari","5684"],["muslim","2217"]],"gr":"صحيح: متفق عليه","dg":"","f":"فيه تصديق قوله تعالى في العسل «فيه شفاء للناس»، والصبر على الدواء حتى يأتي أثره.","en":"Abu Sa'id reported that a man came to the Prophet ﷺ and said: \"My brother has a complaint in his stomach.\" He said: \"Give him honey to drink.\" He came a second time, and he said: \"Give him honey to drink.\" Then he came and said: \"I did.\" He said: \"Allah has spoken the truth, and your brother's stomach has lied. Give him honey to drink.\" So he gave it to him, and he recovered.","ch":"tadawi"},{"id":"sabeen","t":"السبعون ألفاً «لا يسترقون»","x":"… هُمُ الَّذِينَ لاَ يَسْتَرْقُونَ، وَلاَ يَتَطَيَّرُونَ، وَلاَ يَكْتَوُونَ وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ","src":[["bukhari","5705"],["muslim","220"]],"gr":"صحيح: متفق عليه","dg":"","f":"لا يطلبون الرقية من غيرهم كمالاً في التوكل، وهذا لا يمنع أن يرقي المسلم نفسه أو يرقي غيره، ولا يمنع التداوي؛ فقد رقى النبي ﷺ ورُقي وأمر بالتداوي.","en":"\"…they are those who do not ask for ruqyah, do not draw evil omens and do not get cauterised, and in their Lord they put their trust.\"","ch":"tadawi"},{"id":"shirk","t":"«إن الرقى والتمائم والتولة شرك»","x":"عَنْ عَبْدِ اللَّهِ، قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ \" إِنَّ الرُّقَى وَالتَّمَائِمَ وَالتِّوَلَةَ شِرْكٌ \"","src":[["abudawud","3883"]],"gr":"","dg":"الألباني: صحيح؛ شعيب الأرنؤوط: صحيح لغيره؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: ضعيف","f":"المراد رقى الجاهلية التي فيها شرك أو كلام غير معلوم، والتمائم: ما يُعلّق لدفع العين، والتولة: ما يُزعم أنه يحبب المرأة إلى زوجها.","en":"'Abdullah (ibn Mas'ud) said: I heard the Messenger of Allah ﷺ say: \"Spells, amulets and love charms are shirk.\"","ch":"mahadhir"},{"id":"shifaayn","t":"«عليكم بالشفاءين: العسل والقرآن»","x":"عَنْ عَبْدِ اللَّهِ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ  \" عَلَيْكُمْ بِالشِّفَاءَيْنِ الْعَسَلِ وَالْقُرْآنِ \" .","src":[["ibnmajah","3452"]],"gr":"","dg":"الألباني: صحيح موقوف؛ شعيب الأرنؤوط: صحيح موقوف؛ محمد فؤاد عبد الباقي: ضعيف؛ زبير علي زئي: ضعيف","f":"حديث مشهور على الألسنة، والصواب أنه من قول ابن مسعود موقوفاً، أما رفعه إلى النبي ﷺ فضعيف، كما في أحكام المحدثين المثبتة معه.","en":"'Abdullah reported: \"Hold fast to the two healings: honey and the Quran.\"","ch":"mahadhir"},{"id":"ajr","t":"«إن أحق ما أخذتم عليه أجراً كتاب الله»","x":"عَنِ ابْنِ عَبَّاسٍ، أَنَّ نَفَرًا، مِنْ أَصْحَابِ النَّبِيِّ صلى الله عليه وسلم مَرُّوا بِمَاءٍ فِيهِمْ لَدِيغٌ ـ أَوْ سَلِيمٌ ـ فَعَرَضَ لَهُمْ رَجُلٌ مِنْ أَهْلِ الْمَاءِ فَقَالَ هَلْ فِيكُمْ مِنْ رَاقٍ إِنَّ فِي الْمَاءِ رَجُلاً لَدِيغًا أَوْ سَلِيمًا. فَانْطَلَقَ رَجُلٌ مِنْهُمْ فَقَرَأَ بِفَاتِحَةِ الْكِتَابِ عَلَى شَاءٍ، فَبَرَأَ، فَجَاءَ بِالشَّاءِ إِلَى أَصْحَابِهِ فَكَرِهُوا ذَلِكَ وَقَالُوا أَخَذْتَ عَلَى كِتَابِ اللَّهِ أَجْرًا. حَتَّى قَدِمُوا الْمَدِينَةَ فَقَالُوا يَا رَسُولَ اللَّهِ أَخَذَ عَلَى كِتَابِ اللَّهِ أَجْرًا. فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم  \" إِنَّ أَحَقَّ مَا أَخَذْتُمْ عَلَيْهِ أَجْرًا كِتَابُ اللَّهِ \".","src":[["bukhari","5737"]],"gr":"صحيح","dg":"","f":"أجاز النبي ﷺ أخذ الأجر على الرقية بالقرآن. وهذا أصل في حل أجرة الراقي بلا مغالاة ولا استغلال لحاجة المريض.","en":"Some Companions of the Prophet ﷺ passed by a spring where there was a man who had been stung. A man from the people of the spring asked: \"Is there a reciter among you? There is a man stung at the spring.\" One of them went and recited al-Fatihah over a flock of sheep, and the man recovered. He brought the sheep to his companions, who disliked it and said: \"You took a wage for the Book of Allah!\" When they reached Madinah they said: \"O Messenger of Allah, he took a wage for the Book of Allah.\" The Messenger of Allah ﷺ said: \"The most deserving thing for which you may take a wage is the Book of Allah.\"","ch":"x"},{"id":"jann","t":"كان يتعوذ من الجان وعين الإنسان حتى نزلت المعوذتان","x":"عَنْ أَبِي سَعِيدٍ، قَالَ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَتَعَوَّذُ مِنَ الْجَانِّ وَعَيْنِ الإِنْسَانِ حَتَّى نَزَلَتِ الْمُعَوِّذَتَانِ فَلَمَّا نَزَلَتَا أَخَذَ بِهِمَا وَتَرَكَ مَا سِوَاهُمَا","src":[["tirmidhi","2058"]],"gr":"","dg":"الألباني: صحيح؛ أحمد شاكر: صحيح؛ زبير علي زئي: ضعيف","f":"أصل في أن المعوذتين أعظم ما يُتحصَّن به من الجان والعين معاً، وأن النبي ﷺ أخذ بهما وترك ما سواهما.","en":"Abu Sa'id said: The Messenger of Allah ﷺ used to seek refuge from the jinn and from the human eye until the two surahs of refuge were revealed. When they were revealed he took to them and left everything else.","ch":"x"},{"id":"aidh","t":"«أعوذ بكلمات الله التامة من كل شيطان وهامة»","x":"عَنِ ابْنِ عَبَّاسٍ ـ رضى الله عنهما ـ قَالَ كَانَ النَّبِيُّ صلى الله عليه وسلم يُعَوِّذُ الْحَسَنَ وَالْحُسَيْنَ وَيَقُولُ  \" إِنَّ أَبَاكُمَا كَانَ يُعَوِّذُ بِهَا إِسْمَاعِيلَ وَإِسْحَاقَ، أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لاَمَّةٍ","src":[["bukhari","3371"]],"gr":"صحيح","dg":"","f":"تعويذة نبوية تُقال على الأولاد، وفيها الاستعاذة من الشياطين ومن كل ما يؤذي، ومن العين.","en":"Ibn 'Abbas said: The Prophet ﷺ used to seek refuge for al-Hasan and al-Husayn and say: \"Your forefather used to seek refuge with it for Isma'il and Ishaq: I seek refuge in the perfect words of Allah from every devil and every harmful creature, and from every evil eye.\"","ch":"x"},{"id":"shifa7","t":"«أسأل الله العظيم رب العرش العظيم أن يشفيك»","x":"عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ  \" مَنْ عَادَ مَرِيضًا لَمْ يَحْضُرْ أَجَلُهُ فَقَالَ عِنْدَهُ سَبْعَ مِرَارٍ أَسْأَلُ اللَّهَ الْعَظِيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفِيَكَ إِلاَّ عَافَاهُ اللَّهُ مِنْ ذَلِكَ الْمَرَضِ","src":[["abudawud","3106"]],"gr":"","dg":"الألباني: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: إسناده حسن","f":"دعاء للمريض عند زيارته، يُقال سبع مرات، وهو من أيسر الرقى وأقربها للزائر.","en":"Ibn 'Abbas reported from the Prophet ﷺ: \"Whoever visits a sick person whose appointed time has not come and says seven times beside him: I ask Allah the Almighty, Lord of the Mighty Throne, to heal you, Allah will grant him recovery from that illness.\"","ch":"x"},{"id":"arraf","t":"«من أتى عرافاً فسأله عن شيء لم تقبل له صلاة أربعين ليلة»","x":"عَنْ صَفِيَّةَ، عَنْ بَعْضِ، أَزْوَاجِ النَّبِيِّ صلى الله عليه وسلم عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ  \" مَنْ أَتَى عَرَّافًا فَسَأَلَهُ عَنْ شَىْءٍ لَمْ تُقْبَلْ لَهُ صَلاَةٌ أَرْبَعِينَ لَيْلَةً \" .","src":[["muslim","2230"]],"gr":"صحيح","dg":"","f":"سؤال العراف حرام ولو لم يصدقه، وفيه عقوبة تدل على عِظم الأمر. والعراف من يدّعي معرفة المسروق والمفقود ونحوهما بالتخمين أو الإيحاء.","en":"Safiyyah reported from one of the wives of the Prophet ﷺ, from the Prophet ﷺ: \"Whoever goes to a fortune-teller and asks him about anything, his prayer will not be accepted for forty nights.\"","ch":"x"},{"id":"kuhhan","t":"سؤال النبي ﷺ عن الكهان: «ليس بشيء»","x":"عَنْ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ سَأَلَ رَسُولَ اللَّهِ صلى الله عليه وسلم نَاسٌ عَنِ الْكُهَّانِ. فَقَالَ \" لَيْسَ بِشَىْءٍ \". فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّهُمْ يُحَدِّثُونَا أَحْيَانًا بِشَىْءٍ فَيَكُونُ حَقًّا. فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم \" تِلْكَ الْكَلِمَةُ مِنَ الْحَقِّ، يَخْطَفُهَا مِنَ الْجِنِّيِّ، فَيَقُرُّهَا فِي أُذُنِ وَلِيِّهِ، فَيَخْلِطُونَ مَعَهَا مِائَةَ كَذْبَةٍ","src":[["bukhari","5762"]],"gr":"صحيح","dg":"","f":"ما يصدق من كلام الكهان قطعة من استراق الجن يخلطونها بمائة كذبة، فلا يُغتر بإصابتهم أحياناً.","en":"'A'ishah said: Some people asked the Messenger of Allah ﷺ about soothsayers. He said: \"They are nothing.\" They said: \"O Messenger of Allah, they sometimes tell us something that turns out true.\" The Messenger of Allah ﷺ said: \"That word is part of the truth; a jinni snatches it and clucks it into the ear of his friend, and they mix with it a hundred lies.\"","ch":"x"},{"id":"kahin","t":"«من أتى كاهناً فصدقه بما يقول فقد كفر بما أنزل على محمد»","x":"عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ  \" مَنْ أَتَى حَائِضًا أَوِ امْرَأَةً فِي دُبُرِهَا أَوْ كَاهِنًا فَصَدَّقَهُ بِمَا يَقُولُ فَقَدْ كَفَرَ بِمَا أُنْزِلَ عَلَى مُحَمَّدٍ \" .","src":[["ibnmajah","639"]],"gr":"","dg":"الألباني: صحيح؛ شعيب الأرنؤوط: حسن؛ محمد فؤاد عبد الباقي: صحيح؛ زبير علي زئي: حسن","f":"تصديق الكاهن في ادعاء علم الغيب من أعظم الخطر. ويتأكد ذلك في ضوء قوله تعالى: {قل لا يعلم من في السماوات والأرض الغيب إلا الله}.","en":"Abu Hurayrah said: The Messenger of Allah ﷺ said: \"Whoever has intercourse with a menstruating woman, or with a woman in her back passage, or goes to a soothsayer and believes what he says, has disbelieved in what was revealed to Muhammad.\"","ch":"x"},{"id":"nujum","t":"«من اقتبس علماً من النجوم اقتبس شعبة من السحر»","x":"عَنِ ابْنِ عَبَّاسٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم  \" مَنِ اقْتَبَسَ عِلْمًا مِنَ النُّجُومِ اقْتَبَسَ شُعْبَةً مِنَ السِّحْرِ زَادَ مَا زَادَ","src":[["abudawud","3905"]],"gr":"","dg":"الألباني: حسن؛ محيي الدين عبد الحميد: حسن؛ زبير علي زئي: إسناده حسن","f":"ادّعاء الاستدلال بالنجوم على الغيب والحوادث (التنجيم) باب من أبواب السحر، وليس من علم الفلك النافع.","en":"Ibn 'Abbas said: The Messenger of Allah ﷺ said: \"Whoever acquires a branch of knowledge of the stars has acquired a branch of magic; the more he adds, the more he has acquired.\"","ch":"x"},{"id":"mawbiqat","t":"«اجتنبوا السبع الموبقات» وفيها السحر","x":"عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ \" اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ \". قَالُوا يَا رَسُولَ اللَّهِ، وَمَا هُنَّ قَالَ \" الشِّرْكُ بِاللَّهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ، وَالتَّوَلِّي يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ الْغَافِلاَتِ \".","src":[["bukhari","2766"]],"gr":"صحيح","dg":"","f":"جعل النبي ﷺ السحر قرين الشرك في الموبقات، وهذا يبين خطر تعلمه وعمله وإتيان من يعمله.","en":"Abu Hurayrah reported from the Prophet ﷺ: \"Avoid the seven destructive sins.\" They said: \"O Messenger of Allah, what are they?\" He said: \"Associating others with Allah, magic, killing the soul that Allah has forbidden except by right, consuming usury, consuming the property of an orphan, fleeing on the day of battle, and slandering chaste, believing, unsuspecting women.\"","ch":"x"},{"id":"suhira","t":"سحر النبي ﷺ وشفاؤه منه","x":"عَنْ عَائِشَةَ ـ رضى الله عنها ـ قَالَتْ سَحَرَ رَسُولَ اللَّهِ صلى الله عليه وسلم رَجُلٌ مِنْ بَنِي زُرَيْقٍ يُقَالُ لَهُ لَبِيدُ بْنُ الأَعْصَمِ، حَتَّى كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُخَيَّلُ إِلَيْهِ أَنَّهُ يَفْعَلُ الشَّىْءَ وَمَا فَعَلَهُ، حَتَّى إِذَا كَانَ ذَاتَ يَوْمٍ أَوْ ذَاتَ لَيْلَةٍ وَهْوَ عِنْدِي لَكِنَّهُ دَعَا وَدَعَا ثُمَّ قَالَ \" يَا عَائِشَةُ، أَشَعَرْتِ أَنَّ اللَّهَ أَفْتَانِي فِيمَا اسْتَفْتَيْتُهُ فِيهِ، أَتَانِي رَجُلاَنِ فَقَعَدَ أَحَدُهُمَا عِنْدَ رَأْسِي، وَالآخَرُ عِنْدَ رِجْلَىَّ، فَقَالَ أَحَدُهُمَا لِصَاحِبِهِ مَا وَجَعُ الرَّجُلِ فَقَالَ مَطْبُوبٌ. قَالَ مَنْ طَبَّهُ قَالَ لَبِيدُ بْنُ الأَعْصَمِ. قَالَ فِي أَىِّ شَىْءٍ قَالَ فِي مُشْطٍ وَمُشَاطَةٍ، وَجُفِّ طَلْعِ نَخْلَةٍ ذَكَرٍ. قَالَ وَأَيْنَ هُوَ قَالَ فِي بِئْرِ ذَرْوَانَ \". فَأَتَاهَا رَسُولُ اللَّهِ صلى الله عليه وسلم فِي نَاسٍ مِنْ أَصْحَابِهِ فَجَاءَ فَقَالَ \" يَا عَائِشَةُ كَأَنَّ مَاءَهَا نُقَاعَةُ الْحِنَّاءِ، أَوْ كَأَنَّ رُءُوسَ نَخْلِهَا رُءُوسُ الشَّيَاطِينِ \". قُلْتُ يَا رَسُولَ اللَّهِ أَفَلاَ أَسْتَخْرِجُهُ قَالَ \" قَدْ عَافَانِي اللَّهُ، فَكَرِهْتُ أَنْ أُثَوِّرَ عَلَى النَّاسِ فِيهِ شَرًّا \". فَأَمَرَ بِهَا فَدُفِنَتْ","src":[["bukhari","5763"]],"gr":"صحيح","dg":"","f":"السحر وقع للنبي ﷺ في جسده دون أن يمس الوحي والتبليغ، وشفاه الله منه، فلا يُنكر وجوده. وفيه أن الأنبياء لا يُعصمون من الأمراض البدنية.","en":"'A'ishah said: Magic was cast on the Messenger of Allah ﷺ until he imagined he had done something that he had not done. One day he called on his Lord and then said: \"O 'A'ishah, do you know that Allah has answered me concerning what I asked Him? Two men came to me; one sat at my head and the other at my feet. One said to the other: What is the man's ailment? He said: He is bewitched. He said: Who bewitched him? He said: Labid ibn al-A'sam. He said: With what? He said: With a comb and the hair caught in it, and the spathe of a male palm. He said: And where is it? He said: In the well of Dharwan.\" The Messenger of Allah ﷺ went to it with some of his Companions and said: \"O 'A'ishah, its water is like the infusion of henna, and the tops of its palms are like the heads of devils.\" I said: \"O Messenger of Allah, will you not take it out?\" He said: \"Allah has healed me, and I disliked stirring up evil against the people.\" Then he ordered it, and it was buried.","ch":"x"},{"id":"yajri","t":"«إن الشيطان يجري من ابن آدم مجرى الدم»","x":"… أَنَّ صَفِيَّةَ ـ رضى الله عنها ـ أَتَتِ النَّبِيَّ صلى الله عليه وسلم وَهْوَ مُعْتَكِفٌ، فَلَمَّا رَجَعَتْ مَشَى مَعَهَا، فَأَبْصَرَهُ رَجُلٌ مِنَ الأَنْصَارِ، فَلَمَّا أَبْصَرَهُ دَعَاهُ فَقَالَ  \" تَعَالَ هِيَ صَفِيَّةُ ـ وَرُبَّمَا قَالَ سُفْيَانُ هَذِهِ صَفِيَّةُ ـ فَإِنَّ الشَّيْطَانَ يَجْرِي مِنَ ابْنِ آدَمَ مَجْرَى الدَّمِ","src":[["bukhari","2039"]],"gr":"صحيح","dg":"","f":"يدل على قدرة الشيطان على الوسوسة إلى الإنسان وملازمته، فيُتحصَّن منه بذكر الله، ولا يُتوسع في الظن بالناس.","en":"… Safiyyah came to the Prophet ﷺ while he was in seclusion in the mosque. When she went back, he walked with her. A man of the Ansar saw him and the Prophet ﷺ called him and said: \"Come here, this is Safiyyah.\" Then he said: \"Satan flows in the son of Adam like blood.\"","ch":"x"},{"id":"sara","t":"المرأة التي كانت تُصرع فاختارت الصبر","x":"قَالَ لِي ابْنُ عَبَّاسٍ أَلاَ أُرِيكَ امْرَأَةً مِنْ أَهْلِ الْجَنَّةِ قُلْتُ بَلَى. قَالَ هَذِهِ الْمَرْأَةُ السَّوْدَاءُ أَتَتِ النَّبِيَّ صلى الله عليه وسلم فَقَالَتْ إِنِّي أُصْرَعُ، وَإِنِّي أَتَكَشَّفُ فَادْعُ اللَّهَ لِي. قَالَ  \" إِنْ شِئْتِ صَبَرْتِ وَلَكِ الْجَنَّةُ وَإِنْ شِئْتِ دَعَوْتُ اللَّهَ أَنْ يُعَافِيَكِ \". فَقَالَتْ أَصْبِرُ. فَقَالَتْ إِنِّي أَتَكَشَّفُ فَادْعُ اللَّهَ أَنْ لاَ أَتَكَشَّفَ، فَدَعَا لَهَا","src":[["bukhari","5652"]],"gr":"صحيح","dg":"","f":"الصرع المرض فيه أجر الصبر والجنة، وفيه الدعاء بالعافية. ولا يعني الحديث ترك العلاج، بل بيان أن الصبر عليه ثوابه عظيم.","en":"'Ata' ibn Abi Rabah said: Ibn 'Abbas said to me: \"Shall I show you a woman of the people of Paradise?\" I said: \"Yes.\" He said: \"This black woman came to the Prophet ﷺ and said: I suffer seizures and my body becomes uncovered; pray to Allah for me. He said: If you wish, be patient and you will have Paradise, and if you wish I will pray to Allah to heal you. She said: I will be patient. Then she said: But my body becomes uncovered, so pray to Allah that it not become uncovered. So he prayed for her.\"","ch":"x"},{"id":"adhan","t":"الشيطان يدبر عند الأذان","x":"عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ  \" إِذَا نُودِيَ لِلصَّلاَةِ أَدْبَرَ الشَّيْطَانُ وَلَهُ ضُرَاطٌ حَتَّى لاَ يَسْمَعَ التَّأْذِينَ، فَإِذَا قَضَى النِّدَاءَ أَقْبَلَ، حَتَّى إِذَا ثُوِّبَ بِالصَّلاَةِ أَدْبَرَ، حَتَّى إِذَا قَضَى التَّثْوِيبَ أَقْبَلَ حَتَّى يَخْطُرَ بَيْنَ الْمَرْءِ وَنَفْسِهِ، يَقُولُ اذْكُرْ كَذَا، اذْكُرْ كَذَا. لِمَا لَمْ يَكُنْ يَذْكُرُ، حَتَّى يَظَلَّ الرَّجُلُ لاَ يَدْرِي كَمْ صَلَّى","src":[["bukhari","608"]],"gr":"صحيح","dg":"","f":"الأذان من أعظم ما يطرد الشياطين، والصلاة في جماعة وإقامتها في البيت من حصون الحفظ.","en":"Abu Hurayrah reported that the Messenger of Allah ﷺ said: \"When the call to prayer is made, Satan turns his back, passing wind, so that he does not hear the call. When the call ends he returns, and when the iqamah is made he turns his back again, and when it ends he returns, until he comes between a person and his own self, saying: Remember this, remember that, of what he had not been remembering, until the man does not know how much he has prayed.\"","ch":"x"},{"id":"nuzul","t":"«من نزل منزلاً فقال أعوذ بكلمات الله التامات من شر ما خلق»","x":"سَمِعْتُ خَوْلَةَ بِنْتَ حَكِيمٍ السُّلَمِيَّةَ، تَقُولُ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ  \" مَنْ نَزَلَ مَنْزِلاً ثُمَّ قَالَ أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ . لَمْ يَضُرُّهُ شَىْءٌ حَتَّى يَرْتَحِلَ مِنْ مَنْزِلِهِ ذَلِكَ \" .","src":[["muslim","2708"]],"gr":"صحيح","dg":"","f":"تحصين لمن نزل مكاناً في سفر أو نزهة، فلا يصيبه ضرر من شيء حتى يرحل.","en":"Khawlah bint Hakim al-Sulamiyyah said: I heard the Messenger of Allah ﷺ say: \"Whoever stops at a place and then says: I seek refuge in the perfect words of Allah from the evil of what He created, nothing will harm him until he departs from that place.\"","ch":"x"},{"id":"laydurr","t":"«بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء»","x":"سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَقُولُ  \" مَنْ قَالَ بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَىْءٌ فِي الأَرْضِ وَلاَ فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ ثَلاَثَ مَرَّاتٍ لَمْ تُصِبْهُ فَجْأَةُ بَلاَءٍ حَتَّى يُصْبِحَ وَمَنْ قَالَهَا حِينَ يُصْبِحُ ثَلاَثَ مَرَّاتٍ لَمْ تُصِبْهُ فَجْأَةُ بَلاَءٍ حَتَّى يُمْسِيَ \" . قَالَ فَأَصَابَ أَبَانَ بْنَ عُثْمَانَ الْفَالِجُ فَجَعَلَ الرَّجُلُ الَّذِي سَمِعَ مِنْهُ الْحَدِيثَ يَنْظُرُ إِلَيْهِ فَقَالَ لَهُ مَا لَكَ تَنْظُرُ إِلَىَّ فَوَاللَّهِ مَا كَذَبْتُ عَلَى عُثْمَانَ وَلاَ كَذَبَ عُثْمَانُ عَلَى النَّبِيِّ صلى الله عليه وسلم وَلَكِنَّ الْيَوْمَ الَّذِي أَصَابَنِي فِيهِ مَا أَصَابَنِي غَضِبْتُ فَنَسِيتُ أَنْ أَقُولَهَا","src":[["abudawud","5088"]],"gr":"","dg":"الألباني: صحيح؛ زبير علي زئي: صحيح","f":"ذكر صباحي ومسائي، يُقال ثلاث مرات، ومن تركه نسياناً فليقضه متى ذكر.","en":"… I heard the Messenger of Allah ﷺ say: \"Whoever says: In the name of Allah, with whose name nothing on earth or in heaven can cause harm, and He is the All-Hearing, the All-Knowing, three times in the evening, no sudden calamity will strike him until morning; and whoever says it three times in the morning, no sudden calamity will strike him until evening.\" Aban ibn 'Uthman was then struck with paralysis, and the man who had heard the hadith from him kept looking at him. He said to him: \"Why do you look at me? By Allah, I have not lied about 'Uthman, nor did 'Uthman lie about the Prophet ﷺ; but on the day this befell me I was angry and forgot to say it.\"","ch":"x"},{"id":"takfik","t":"«قل هو الله أحد والمعوذتين حين تمسي وحين تصبح ثلاث مرات تكفيك من كل شيء»","x":"… فَقَالَ \" أَصَلَّيْتُمْ \" . فَلَمْ أَقُلْ شَيْئًا فَقَالَ \" قُلْ \" . فَلَمْ أَقُلْ شَيْئًا ثُمَّ قَالَ \" قُلْ \" . فَلَمْ أَقُلْ شَيْئًا ثُمَّ قَالَ \" قُلْ \" . فَقُلْتُ يَا رَسُولَ اللَّهِ مَا أَقُولُ قَالَ \" { قُلْ هُوَ اللَّهُ أَحَدٌ } وَالْمُعَوِّذَتَيْنِ حِينَ تُمْسِي وَحِينَ تُصْبِحُ ثَلاَثَ مَرَّاتٍ تَكْفِيكَ مِنْ كُلِّ شَىْءٍ","src":[["abudawud","5082"]],"gr":"","dg":"الألباني: حسن؛ شعيب الأرنؤوط: حسن صحيح؛ محيي الدين عبد الحميد: حسن؛ زبير علي زئي: إسناده حسن","f":"ورد الصباح والمساء من الإخلاص والمعوذتين ثلاثاً، وهو أصل التحصين اليومي للمسلم.","en":"… He said: \"Did you pray?\" I said nothing. He said: \"Say.\" I said nothing. Then he said: \"Say.\" I said: \"O Messenger of Allah, what shall I say?\" He said: \"Say: He is Allah, the One, and the two surahs of refuge, in the evening and in the morning, three times; they will suffice you against everything.\"","ch":"x"},{"id":"hirz","t":"«كانت له حرزاً من الشيطان يومه ذلك حتى يمسي»","x":"عَنْ أَبِي هُرَيْرَةَ ـ رضى الله عنه ـ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ  \" مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ. فِي يَوْمٍ مِائَةَ مَرَّةٍ، كَانَتْ لَهُ عَدْلَ عَشْرِ رِقَابٍ، وَكُتِبَتْ لَهُ مِائَةُ حَسَنَةٍ، وَمُحِيَتْ عَنْهُ مِائَةُ سَيِّئَةٍ، وَكَانَتْ لَهُ حِرْزًا مِنَ الشَّيْطَانِ يَوْمَهُ ذَلِكَ حَتَّى يُمْسِيَ، وَلَمْ يَأْتِ أَحَدٌ بِأَفْضَلَ مِمَّا جَاءَ بِهِ، إِلاَّ أَحَدٌ عَمِلَ أَكْثَرَ مِنْ ذَلِكَ","src":[["bukhari","3293"]],"gr":"صحيح","dg":"","f":"ذكر التهليل مئة مرة في اليوم حرز من الشيطان لقائله، مع ما فيه من أجور عظيمة.","en":"Abu Hurayrah reported that the Messenger of Allah ﷺ said: \"Whoever says: There is no god but Allah alone, with no partner; His is the dominion and His is the praise, and He has power over all things, a hundred times in a day, it will be equal to freeing ten slaves, a hundred good deeds will be recorded for him, a hundred sins will be erased, and it will be a protection for him from Satan on that day until evening; and no one will bring anything better than what he brought, except one who did more than that.\"","ch":"x"},{"id":"dukhul","t":"ذكر الله عند دخول البيت وعند الطعام","x":"عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّهُ سَمِعَ النَّبِيَّ صلى الله عليه وسلم يَقُولُ  \" إِذَا دَخَلَ الرَّجُلُ بَيْتَهُ فَذَكَرَ اللَّهَ عِنْدَ دُخُولِهِ وَعِنْدَ طَعَامِهِ قَالَ الشَّيْطَانُ لاَ مَبِيتَ لَكُمْ وَلاَ عَشَاءَ . وَإِذَا دَخَلَ فَلَمْ يَذْكُرِ اللَّهَ عِنْدَ دُخُولِهِ قَالَ الشَّيْطَانُ أَدْرَكْتُمُ الْمَبِيتَ . وَإِذَا لَمْ يَذْكُرِ اللَّهَ عِنْدَ طَعَامِهِ قَالَ أَدْرَكْتُمُ الْمَبِيتَ وَالْعَشَاءَ \" .","src":[["muslim","2018"]],"gr":"صحيح","dg":"","f":"من ذكر الله عند دخول بيته وعند أكله حُرم الشيطان مبيته وعشاءه، فالبيت يتحصن بالذكر عند الدخول.","en":"Jabir ibn 'Abdullah heard the Prophet ﷺ say: \"When a man enters his house and mentions Allah on entering and at his meal, Satan says: You have no lodging and no supper. And when he enters without mentioning Allah on entering, Satan says: You have found lodging. And when he does not mention Allah at his meal, Satan says: You have found lodging and supper.\"","ch":"x"},{"id":"jinh","t":"«أغلقوا الأبواب واذكروا اسم الله» عند دخول الليل","x":"عَنْ جَابِرٍ، عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم أَنَّهُ قَالَ \" غَطُّوا الإِنَاءَ وَأَوْكُوا السِّقَاءَ وَأَغْلِقُوا الْبَابَ وَأَطْفِئُوا السِّرَاجَ فَإِنَّ الشَّيْطَانَ لاَ يَحُلُّ سِقَاءً وَلاَ يَفْتَحُ بَابًا وَلاَ يَكْشِفُ إِنَاءً فَإِنْ لَمْ يَجِدْ أَحَدُكُمْ إِلاَّ أَنْ يَعْرُضَ عَلَى إِنَائِهِ عُودًا وَيَذْكُرَ اسْمَ اللَّهِ فَلْيَفْعَلْ فَإِنَّ الْفُوَيْسِقَةَ تُضْرِمُ عَلَى أَهْلِ الْبَيْتِ بَيْتَهُمْ","src":[["muslim","2012"]],"gr":"صحيح","dg":"","f":"آداب للبيت عند المساء: كفّ الصبيان، وإغلاق الباب، وتغطية الأواني، وإطفاء السراج، مع ذكر اسم الله على كل ذلك.","en":"Jabir ibn 'Abdullah said: The Messenger of Allah ﷺ said: \"When night falls, or when you reach evening, keep your children in, for Satan spreads out at that time. When an hour of the night has passed, let them go. Close the doors and mention the name of Allah, for Satan does not open a closed door. Tie your waterskins and mention the name of Allah; cover your vessels and mention the name of Allah, even by laying something across them; and put out your lamps, for the mischief-maker may set a house on fire over its people.\"","ch":"x"},{"id":"kharaj","t":"«بسم الله توكلت على الله ولا حول ولا قوة إلا بالله» عند الخروج","x":"عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ \" إِذَا خَرَجَ الرَّجُلُ مِنْ بَيْتِهِ فَقَالَ بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ \" . قَالَ \" يُقَالُ حِينَئِذٍ هُدِيتَ وَكُفِيتَ وَوُقِيتَ فَتَتَنَحَّى لَهُ الشَّيَاطِينُ فَيَقُولُ لَهُ شَيْطَانٌ آخَرُ كَيْفَ لَكَ بِرَجُلٍ قَدْ هُدِيَ وَكُفِيَ وَوُقِيَ","src":[["abudawud","5095"]],"gr":"","dg":"الألباني: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: حسن","f":"ذكر الخروج من البيت، وفيه هداية وكفاية ووقاية، وتتنحى به الشياطين عن قائله.","en":"Anas ibn Malik reported that the Prophet ﷺ said: \"When a man leaves his house and says: In the name of Allah, I place my trust in Allah, there is no power or might but with Allah, it is said to him then: You are guided, defended and protected. The devils withdraw from him, and another devil says to him: How can you deal with a man who has been guided, defended and protected?\"","ch":"x"},{"id":"ghadab","t":"«أعوذ بالله من الشيطان» عند الغضب","x":"قَالَ كُنْتُ جَالِسًا مَعَ النَّبِيِّ صلى الله عليه وسلم وَرَجُلاَنِ يَسْتَبَّانِ، فَأَحَدُهُمَا احْمَرَّ وَجْهُهُ وَانْتَفَخَتْ أَوْدَاجُهُ، فَقَالَ النَّبِيُّ صلى الله عليه وسلم \" إِنِّي لأَعْلَمُ كَلِمَةً لَوْ قَالَهَا ذَهَبَ عَنْهُ مَا يَجِدُ، لَوْ قَالَ أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ. ذَهَبَ عَنْهُ مَا يَجِدُ \". فَقَالُوا لَهُ إِنَّ النَّبِيَّ صلى الله عليه وسلم قَالَ \" تَعَوَّذْ بِاللَّهِ مِنَ الشَّيْطَانِ \". فَقَالَ وَهَلْ بِي جُنُونٌ","src":[["bukhari","3282"]],"gr":"صحيح","dg":"","f":"الغضب من مداخل الشيطان، وعلاجه التعوذ بالله منه، وقد لا ينتبه الغاضب لحاله فينبغي تذكيره بلطف.","en":"Sulayman ibn Surad said: I was sitting with the Prophet ﷺ while two men were insulting each other. One of them had a reddened face and swollen veins. The Prophet ﷺ said: \"I know a word which, if he said it, what he feels would leave him: if he said, I seek refuge in Allah from Satan, what he feels would leave him.\" They said to him: \"The Prophet ﷺ said: Seek refuge in Allah from Satan.\" He said: \"Am I mad?\"","ch":"x"},{"id":"jinab","t":"«بسم الله اللهم جنبنا الشيطان وجنب الشيطان ما رزقتنا»","x":"عَنِ ابْنِ عَبَّاسٍ، يَبْلُغُ بِهِ النَّبِيَّ صلى الله عليه وسلم قَالَ  \" لَوْ أَنَّ أَحَدَكُمْ إِذَا أَتَى أَهْلَهُ قَالَ بِسْمِ اللَّهِ اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا. فَقُضِيَ بَيْنَهُمَا وَلَدٌ، لَمْ يَضُرَّهُ","src":[["bukhari","141"]],"gr":"صحيح","dg":"","f":"دعاء الزوج عند إتيان أهله، وفيه حفظ الذرية من ضرر الشيطان.","en":"Ibn 'Abbas reported from the Prophet ﷺ: \"If any of you, when he comes to his wife, says: In the name of Allah. O Allah, keep Satan away from us and keep Satan away from what You provide us, and a child is decreed for them, Satan will never harm it.\"","ch":"x"},{"id":"khubuth","t":"«اللهم إني أعوذ بك من الخبث والخبائث» عند دخول الخلاء","x":"… سَمِعْتُ أَنَسًا، يَقُولُ كَانَ النَّبِيُّ صلى الله عليه وسلم إِذَا دَخَلَ الْخَلاَءَ قَالَ  \" اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ","src":[["bukhari","142"]],"gr":"صحيح","dg":"","f":"الخلاء من مواضع الشياطين، فيُتحصَّن عند دخوله بهذا الذكر.","en":"… I heard Anas say: When the Prophet ﷺ entered the toilet he said: \"O Allah, I seek refuge in You from the male and female devils.\"","ch":"x"},{"id":"sakan","t":"«اجعلوا في بيوتكم من صلاتكم ولا تتخذوها قبوراً»","x":"عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ  \" اجْعَلُوا فِي بُيُوتِكُمْ مِنْ صَلاَتِكُمْ، وَلاَ تَتَّخِذُوهَا قُبُورًا \".","src":[["bukhari","432"]],"gr":"صحيح","dg":"","f":"إحياء البيت بالصلاة والقرآن يحصنه، والبيت الذي لا يُذكر فيه الله كالمقبرة.","en":"Ibn 'Umar reported from the Prophet ﷺ: \"Make some of your prayer in your homes and do not make them graves.\"","ch":"x"},{"id":"awamir","t":"حيات البيوت وإنذار الجن قبل قتلها","x":"… فَجِئْنَا إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَذَكَرْنَا ذَلِكَ لَهُ وَقُلْنَا ادْعُ اللَّهَ يُحْيِيهِ لَنَا . فَقَالَ \" اسْتَغْفِرُوا لِصَاحِبِكُمْ \" . ثُمَّ قَالَ \" إِنَّ بِالْمَدِينَةِ جِنًّا قَدْ أَسْلَمُوا فَإِذَا رَأَيْتُمْ مِنْهُمْ شَيْئًا فَآذِنُوهُ ثَلاَثَةَ أَيَّامٍ فَإِنْ بَدَا لَكُمْ بَعْدَ ذَلِكَ فَاقْتُلُوهُ فَإِنَّمَا هُوَ شَيْطَانٌ \" .","src":[["muslim","2236"]],"gr":"صحيح","dg":"","f":"يدل الحديث على أن للجن حقاً في الأمان، وأن الاعتداء عليهم بغير إنذار من أسباب الأذى، فيُتورع في قتل ما يعمر البيوت من الحيات إلا بعد الإنذار.","en":"… We came to the Messenger of Allah ﷺ and mentioned that to him and said: \"Pray to Allah to bring him back to life for us.\" He said: \"Seek forgiveness for your companion.\" Then he said: \"In Madinah there are jinn who have accepted Islam. If you see any of them, warn it for three days; if it appears to you after that, kill it, for it is a devil.\"","ch":"x"},{"id":"baqara3","t":"الآيتان من آخر سورة البقرة لا يقربهما شيطان ثلاث ليال","x":"عَنِ النُّعْمَانِ بْنِ بَشِيرٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ  \" إِنَّ اللَّهَ كَتَبَ كِتَابًا قَبْلَ أَنْ يَخْلُقَ السَّمَاوَاتِ وَالأَرْضَ بِأَلْفَىْ عَامٍ أَنْزَلَ مِنْهُ آيَتَيْنِ خَتَمَ بِهِمَا سُورَةَ الْبَقَرَةِ وَلاَ يُقْرَآنِ فِي دَارٍ ثَلاَثَ لَيَالٍ فَيَقْرَبُهَا شَيْطَانٌ","src":[["tirmidhi","2882"]],"gr":"","dg":"الألباني: صحيح؛ أحمد شاكر: صحيح؛ زبير علي زئي: إسناده حسن","f":"قراءة خواتيم البقرة في الدار من أسباب حفظها، وقد تقدم في الباب حديث قراءة البقرة في البيوت.","en":"Al-Nu'man ibn Bashir reported from the Prophet ﷺ: \"Allah wrote a book two thousand years before He created the heavens and the earth, and from it He sent down two verses with which He concluded Surat al-Baqarah. They are not recited in a house for three nights without a devil coming near it.\"","ch":"x"},{"id":"ayn2","t":"«العين حق»","x":"عَنْ أَبِيهِ، عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ  \" الْعَيْنُ حَقٌّ وَلَوْ كَانَ شَىْءٌ سَابَقَ الْقَدَرَ سَبَقَتْهُ الْعَيْنُ وَإِذَا اسْتُغْسِلْتُمْ فَاغْسِلُوا","src":[["muslim","2188"]],"gr":"صحيح","dg":"","f":"العين حق، وعلاجها الرقية بالمعوذات وما ثبت، وقد يُطلب من العائن ما يُشرع في هذا الباب.","en":"… from Ibn 'Abbas, from the Prophet ﷺ: \"The evil eye is real; if anything could outstrip the decree, the evil eye would outstrip it. And when you are asked to wash, then wash.\"","ch":"x"},{"id":"khinzab","t":"وسوسة الشيطان في الصلاة: «ذاك شيطان يقال له خنزب»","x":"أَنَّ عُثْمَانَ بْنَ أَبِي الْعَاصِ، أَتَى النَّبِيَّ صلى الله عليه وسلم فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ الشَّيْطَانَ قَدْ حَالَ بَيْنِي وَبَيْنَ صَلاَتِي وَقِرَاءَتِي يَلْبِسُهَا عَلَىَّ . فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم  \" ذَاكَ شَيْطَانٌ يُقَالُ لَهُ خِنْزِبٌ فَإِذَا أَحْسَسْتَهُ فَتَعَوَّذْ بِاللَّهِ مِنْهُ وَاتْفِلْ عَلَى يَسَارِكَ ثَلاَثًا \" . قَالَ فَفَعَلْتُ ذَلِكَ فَأَذْهَبَهُ اللَّهُ عَنِّي","src":[["muslim","2203"]],"gr":"صحيح","dg":"","f":"علاج الوسوسة في الصلاة: التعوذ بالله من الشيطان والتفل عن اليسار ثلاثاً، ولم يأمر النبي ﷺ بأكثر من ذلك.","en":"… 'Uthman ibn Abi al-'As came to the Prophet ﷺ and said: \"O Messenger of Allah, Satan has come between me and my prayer and my recitation and confuses me in them.\" The Messenger of Allah ﷺ said: \"That is a devil called Khinzab. When you feel him, seek refuge in Allah from him and spit lightly to your left three times.\" He said: I did so, and Allah removed him from me.","ch":"x"},{"id":"nushra","t":"«النشرة من عمل الشيطان»","x":"عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ سُئِلَ رَسُولُ اللَّهِ صلى الله عليه وسلم عَنِ النُّشْرَةِ فَقَالَ  \" هُوَ مِنْ عَمَلِ الشَّيْطَانِ \" .","src":[["abudawud","3868"]],"gr":"","dg":"الألباني: صحيح؛ شعيب الأرنؤوط: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: إسناده حسن","f":"النشرة هي حل السحر عن المسحور. والمنهي عنه منها ما كان بسحر مثله أو بما فيه استعانة بالشياطين، أما الحل بالرقية الشرعية والتعوذ والدواء المباح فجائز عند أهل العلم.","en":"Jabir ibn 'Abdullah said: The Messenger of Allah ﷺ was asked about nushrah and said: \"It is from the work of Satan.\"","ch":"x"},{"id":"khamr","t":"«إنه ليس بدواء ولكنه داء»","x":"أَنَّ طَارِقَ بْنَ سُوَيْدٍ الْجُعْفِيَّ، سَأَلَ النَّبِيَّ صلى الله عليه وسلم عَنِ الْخَمْرِ فَنَهَا أَوْ كَرِهَ أَنْ يَصْنَعَهَا فَقَالَ إِنَّمَا أَصْنَعُهَا لِلدَّوَاءِ فَقَالَ  \" إِنَّهُ لَيْسَ بِدَوَاءٍ وَلَكِنَّهُ دَاءٌ \" .","src":[["muslim","1984"]],"gr":"صحيح","dg":"","f":"لا يُتداوى بمحرم كالخمر، وكذلك لا يُستعان في العلاج بما حرمه الله من نجاسات أو دماء أو ما فيه شرك.","en":"Tariq ibn Suwayd al-Ju'fi asked the Prophet ﷺ about wine and he forbade it, or disliked that he make it. He said: \"I make it only as a medicine.\" The Prophet ﷺ said: \"It is not a medicine but a disease.\"","ch":"x"},{"id":"dhabh","t":"«لعن الله من ذبح لغير الله»","x":"… غَيْرَ أَنَّهُ قَدْ حَدَّثَنِي بِكَلِمَاتٍ أَرْبَعٍ . قَالَ فَقَالَ مَا هُنَّ يَا أَمِيرَ الْمُؤْمِنِينَ قَالَ قَالَ  \" لَعَنَ اللَّهُ مَنْ لَعَنَ وَالِدَهُ وَلَعَنَ اللَّهُ مَنْ ذَبَحَ لِغَيْرِ اللَّهِ وَلَعَنَ اللَّهُ مَنْ آوَى مُحْدِثًا وَلَعَنَ اللَّهُ مَنْ غَيَّرَ مَنَارَ الأَرْضِ \" .","src":[["muslim","1978"]],"gr":"صحيح","dg":"","f":"الذبح لغير الله شرك. فمن طلب منك ذبح حيوان بصفات معينة أو دمه لجني أو لغيره فليس راقياً شرعياً.","en":"… except that he told me four things. He said: \"What are they, Commander of the Believers?\" He said: The Prophet ﷺ said: \"Allah has cursed whoever curses his father; Allah has cursed whoever slaughters for other than Allah; Allah has cursed whoever shelters an innovator; and Allah has cursed whoever alters the landmarks of the land.\"","ch":"x"},{"id":"khalwa","t":"«لا يخلون رجل بامرأة إلا مع ذي محرم»","x":"عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صلى الله عليه وسلم قَالَ \" لاَ يَخْلُوَنَّ رَجُلٌ بِامْرَأَةٍ إِلاَّ مَعَ ذِي مَحْرَمٍ","src":[["bukhari","5233"]],"gr":"صحيح","dg":"","f":"ضابط شرعي يلزم كل راقٍ ومعالج: لا خلوة بأجنبية، ولا لمس لها، بل تكون الرقية بحضور محرمها.","en":"Ibn 'Abbas reported from the Prophet ﷺ: \"No man should be alone with a woman unless a mahram is with her.\"","ch":"x"},{"id":"darar","t":"«لا ضرر ولا ضرار»","x":"عَنْ عُبَادَةَ بْنِ الصَّامِتِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَضَى أَنْ  \" لاَ ضَرَرَ وَلاَ ضِرَارَ \" .","src":[["ibnmajah","2340"]],"gr":"","dg":"الألباني: صحيح؛ شعيب الأرنؤوط: صحيح لغيره؛ محمد فؤاد عبد الباقي: صحيح؛ زبير علي زئي: ضعيف","f":"قاعدة تمنع إيذاء المريض بضرب أو خنق أو إهانة بدعوى إخراج جني، فالرقية دعاء وقراءة، لا عنف.","en":"'Ubadah ibn al-Samit reported that the Messenger of Allah ﷺ ruled that: \"There is to be no harm and no reciprocating harm.\"","ch":"x"}],"q":[{"w":"القرطبي","bk":"qurtubi","s":17,"ay":82,"x":"اخْتَلَفَ الْعُلَمَاءُ فِي كَوْنِهِ شِفَاءً عَلَى قَوْلَيْنِ: أَحَدُهُمَا: أَنَّهُ شِفَاءٌ لِلْقُلُوبِ بِزَوَالِ الْجَهْلِ عَنْهَا وَإِزَالَةِ الرَّيْبِ، وَلِكَشْفِ غِطَاءِ الْقَلْبِ مِنْ مَرَضِ الْجَهْلِ لِفَهْمِ الْمُعْجِزَاتِ وَالْأُمُورِ الدَّالَّةِ عَلَى اللَّهِ تَعَالَى. الثَّانِي: شِفَاءٌ مِنَ الْأَمْرَاضِ الظَّاهِرَةِ بِالرُّقَى وَالتَّعَوُّذِ وَنَحْوِهِ.","n":"قولان في معنى الشفاء، والثاني يدخل فيه شفاء الأبدان بالرقية.","en":"Scholars differed on how it is healing, holding two views. First: it is healing for hearts by removing ignorance and doubt from them, and by lifting the cover of the disease of ignorance from the heart so that it understands the miracles and the signs pointing to Allah. Second: it is healing from outward illnesses through ruqyah, seeking refuge and the like."},{"w":"ابن كثير","bk":"ibnkathir","s":17,"ay":82,"x":"أَيْ: يُذْهِبُ مَا فِي الْقُلُوبِ مِنْ أَمْرَاضٍ، مِنْ شَكٍّ وَنِفَاقٍ، وَشِرْكٍ وَزَيْغٍ وَمَيْلٍ، فَالْقُرْآنُ يَشْفِي مِنْ ذَلِكَ كُلِّهِ. وَهُوَ أَيْضًا رَحْمَةٌ يَحْصُلُ فِيهَا الْإِيمَانُ وَالْحِكْمَةُ وَطَلَبُ الْخَيْرِ وَالرَّغْبَةُ فِيهِ، وَلَيْسَ هَذَا إِلَّا لِمَنْ آمَنَ بِهِ وَصَدَّقَهُ وَاتَّبَعَهُ، فَإِنَّهُ يَكُونُ شِفَاءً فِي حَقِّهِ وَرَحْمَةً.","n":"شفاء القرآن لأمراض القلوب خاص بمن آمن به واتبعه.","en":"That is: it removes the diseases in hearts, such as doubt, hypocrisy, shirk, deviation and inclination; the Quran heals all of that. It is also a mercy through which faith, wisdom and the pursuit of good are attained. This is only for whoever believes in it, affirms it and follows it; for him it is healing and mercy."},{"w":"السعدي","bk":"saadi","s":17,"ay":82,"x":"فالشفاء الذي تضمنَّه القرآن عامٌّ لشفاء القلوب من الشُّبه والجهالة والآراء الفاسدة والانحراف السيئ والقصود السيئة؛ فإنه مشتملٌ على العلم اليقيني الذي تزول به كلُّ شبهة وجهالة، والوعظ والتذكير الذي يزول به كلُّ شهوة تخالف أمر الله، ولشفاء الأبدان من آلامها وأسقامها","n":"شفاء القرآن عام للقلوب والأبدان.","en":"The healing contained in the Quran is general: healing of hearts from doubts, ignorance, corrupt opinions, evil deviation and evil intentions, for it contains certain knowledge that removes every doubt and ignorance, and admonition and reminder that remove every desire contrary to the command of Allah; and healing of bodies from their pains and illnesses."},{"w":"السعدي","bk":"saadi","s":41,"ay":44,"x":"وشفاءٌ لهم من الأسقام البدنيَّة والأسقام القلبيَّة؛ لأنَّه يزجر عن مساوئ الأخلاق وأقبح الأعمال، ويحث على التوبة النَّصوح التي تغسل الذُّنوب وتشفي القلب.","n":"في تفسير آية فصلت.","en":"And a healing for them from bodily and spiritual illnesses, because it restrains from bad manners and the ugliest deeds, and urges sincere repentance that washes away sins and heals the heart."},{"w":"السعدي","bk":"saadi","s":113,"ay":1,"x":"ويدخل في الحاسد العاينُ؛ لأنَّه لا تصدر العين إلاَّ من حاسدٍ شرِّيرِ الطبع خبيث النفس.","n":"في تفسير سورة الفلق: العين من الحسد.","en":"The one who casts the evil eye is included in \"the envier\", because the evil eye only comes from an envious person of evil nature and wicked soul."},{"w":"ابن حجر العسقلاني","ref":"فتح الباري، كتاب الطب، باب الرقى بالقرآن والمعوذات","x":"وقد أجمع العلماء على جواز الرقى عند اجتماع ثلاثة شروط: أن يكون بكلام الله تعالى أو بأسمائه وصفاته، وباللسان العربي أو بما يعرف معناه من غيره، وأن يعتقد أن الرقية لا تؤثر بذاتها بل بذات الله تعالى.","n":"أصل الضوابط الثلاثة المشهورة.","en":"Scholars agree that ruqyah is permitted when three conditions are met: that it be with the words of Allah or His names and attributes; that it be in Arabic or in a language whose meaning is understood; and that one believe ruqyah has no effect by itself but only by Allah.","ext":1},{"w":"ابن قيم الجوزية","ref":"زاد المعاد في هدي خير العباد، فصل الطب النبوي: في هديه ﷺ في علاج المصاب","x":"فالقرآن هو الشفاء التام من جميع الأدواء القلبية والبدنية، وأدواء الدنيا والآخرة، وما كل أحد يؤهل ولا يوفق للاستشفاء به، وإذا أحسن العليل التداوي به، ووضعه على دائه بصدق وإيمان، وقبول تام، واعتقاد جازم، واستيفاء شروطه، لم يقاومه الداء أبداً.","n":"الانتفاع بالرقية بقدر صدق الراقي والمرقي وإيمانهما.","en":"The Quran is the complete healing for all diseases of the heart and body, and the diseases of this world and the Hereafter. Not everyone is qualified or enabled to seek healing through it. When the sick person seeks treatment with it well, applying it to his illness with sincerity and faith, full acceptance, firm conviction and fulfilment of its conditions, the illness can never withstand it.","ext":1},{"id":"q-mass","w":"القرطبي","bk":"qurtubi","s":2,"ay":275,"x":"فِي هَذِهِ الْآيَةِ دَلِيلٌ عَلَى فَسَادِ إِنْكَارِ مَنْ أَنْكَرَ الصَّرْعَ مِنْ جِهَةِ الْجِنِّ، وَزَعَمَ أَنَّهُ مِنْ فِعْلِ الطَّبَائِعِ، وَأَنَّ الشَّيْطَانَ لَا يَسْلُكُ فِي الْإِنْسَانِ وَلَا يَكُونُ مِنْهُ مَسٌّ، وَقَدْ مَضَى الرَّدُّ عَلَيْهِمْ فِيمَا تَقَدَّمَ مِنْ هَذَا الْكِتَابِ","n":"ردّ على من أنكر المس والصرع من جهة الجن، واستدلال بالآية على وقوعه.","en":"In this verse is proof of the error of one who denied seizure by the jinn, claiming it is the work of natural humours and that Satan does not enter a person and there is no touch from him; the reply to them was given earlier in this book.","ch":"x"},{"id":"q-sihr-haq","w":"القرطبي","bk":"qurtubi","s":2,"ay":102,"x":"وَاخْتُلِفَ هَلْ لَهُ حَقِيقَةٌ أَمْ لَا، فَذَكَرَ الْغَزْنَوِيُّ الْحَنَفِيُّ فِي عُيُونِ الْمَعَانِي لَهُ: أَنَّ السِّحْرَ الْمُعْتَزِلَةِ خُدَعٌ لَا أَصْلَ لَهُ، وَعِنْدَ الشَّافِعِيِّ وَسْوَسَةٌ وَأَمْرَاضٌ. قَالَ: وَعِنْدَنَا أَصْلُهُ طِلَّسْمٌ يُبْنَى عَلَى تَأْثِيرِ خَصَائِصِ الْكَوَاكِبِ، كَتَأْثِيرِ الشَّمْسِ فِي زِئْبَقِ عِصِيِّ فِرْعَوْنَ، أَوْ تَعْظِيمِ الشَّيَاطِينِ لِيُسَهِّلُوا لَهُ مَا عَسُرَ. قُلْتُ: وَعِنْدَنَا أَنَّهُ حَقٌّ وَلَهُ حَقِيقَةٌ يَخْلُقُ اللَّهُ عِنْدَهُ مَا شَاءَ، عَلَى مَا يَأْتِي","n":"خلاف العلماء في حقيقة السحر، واختيار القرطبي أن له حقيقة يخلق الله عندها ما شاء.","en":"There is a difference over whether it has any reality. Al-Ghaznawi the Hanafi mentioned in his book that magic, according to the Mu'tazilah, is trickery with no basis, and according to al-Shafi'i it is whispering and illnesses. He said: \"With us its basis is a talisman built on the effect of the properties of the stars, as the sun's effect on the quicksilver in Pharaoh's staffs, or on glorifying the devils so that they make easy for him what is hard.\" I say: With us it is true and has a reality; Allah creates at it whatever He wills, as will come.","ch":"x"},{"id":"q-sihr-anwa","w":"القرطبي","bk":"qurtubi","s":2,"ay":102,"x":"ثُمَّ مِنَ السِّحْرِ مَا يَكُونُ بِخِفَّةِ الْيَدِ كَالشَّعْوَذَةِ. وَالشَّعْوَذِيُّ: الْبَرِيدُ لِخِفَّةِ سَيْرِهِ. قَالَ ابْنُ فَارِسٍ فِي الْمُجْمَلِ: الشَّعْوَذَةُ لَيْسَ مِنْ كَلَامِ أَهْلِ الْبَادِيَةِ، وَهِيَ خِفَّةٌ فِي الْيَدَيْنِ وَأَخْذَةٌ كَالسِّحْرِ، وَمِنْهُ مَا يَكُونُ كَلَامًا يُحْفَظُ، وَرُقًى مِنْ أَسْمَاءِ اللَّهِ تَعَالَى. وَقَدْ يَكُونُ مِنْ عُهُودِ الشَّيَاطِينِ، وَيَكُونُ أَدْوِيَةً وأدخنة وغير ذلك","n":"بيان أن من السحر ما هو خفة يد وشعوذة، ومنه ما يكون بعهود الشياطين.","en":"Then some magic is by sleight of hand, such as conjuring. The conjurer is \"al-barid\" because of the lightness of his running. Ibn Faris said in al-Mujmal: conjuring is not from the speech of the Bedouin; it is a lightness in the two hands and a seizing like magic. Some of it is words that are memorised, and ruqyahs from the names of Allah, and some may be from the pacts of the devils, and some medicines and fumigations and other things.","ch":"x"},{"id":"q-sihr-idhn","w":"السعدي","bk":"saadi","s":2,"ay":102,"x":"وفي هذه الآية وما أشبهها أن الأسباب\nمهما بلغت في قوة التأثير فإنها تابعة للقضاء والقدر ليست مستقلة في التأثير","n":"أصل تتحصن به القلوب: السحر وغيره من الأسباب لا يؤثر إلا بقضاء الله وقدره.","en":"And in this verse and its like: causes, however strong their effect, follow the decree and destiny and are not independent in their effect.","ch":"x"},{"id":"q-falaq","w":"السعدي","bk":"saadi","s":113,"ay":4,"x":"فهذه السورة تضمَّنت الاستعاذة من جميع أنواع الشُّرور عموماً وخصوصاً، ودلَّت على أنَّ السِّحر له حقيقةٌ؛ يُخشى من ضرره، ويستعاذ بالله منه ومن أهله","n":"تقرير أن السحر له حقيقة، وأن العلاج منه الاستعاذة بالله.","en":"This surah contains seeking refuge from all kinds of evils, general and specific, and it indicates that magic is real, that its harm is to be feared, and that refuge is to be sought in Allah from it and from its people.","ch":"x"},{"id":"q-jinn6","w":"السعدي","bk":"saadi","s":72,"ay":6,"x":"أي: كان الإنس يعوذون بالجنِّ عند المخاوف والأفزاع ويعبُدونهم،\nفزاد الإنسُ الجنَّ رهقاً؛ أي: طغياناً وتكبراً، لمَّا رأوا الإنس\nيعبدونَهم ويستعيذون بهم، ويُحتمل أنَّ الضمير وهي الواو ترجع إلى {الجنِّ}؛ أي: زاد الجنُّ الإنسَ ذُعْراً\nوتخويفاً لما رأوْهم يستعيذون بهم ليلجِئوهم إلى الاستعاذة بهم والتمسُّك بما هم عليه، فكان\nالإنسيُّ إذا نزل بوادٍ مخوفٍ؛ قال: أعوذ بسيِّد هذا الوادي من سفهاء قومه","n":"بيان خطر الاستعانة بالجن والاستعاذة بهم، وأنها من أسباب زيادة تسلطهم.","en":"That is: men used to seek refuge in the jinn at times of fear and alarm and worship them, so men increased the jinn in arrogance and pride when they saw men worshipping them and seeking refuge in them. It may also be that the pronoun refers to the jinn, meaning the jinn increased men in terror and fear when they saw them seeking refuge in them, to make them take shelter in them and cling to what they were on. So when a man stopped in a frightening valley, he would say: I seek refuge in the master of this valley from the fools of his people.","ch":"x"},{"id":"q-ziker","w":"السعدي","bk":"saadi","s":43,"ay":36,"x":"يخبر تعالى عن عقوبَتهِ البليغةِ بمن أعرضَ عن ذكرِهِ، فقال:{ومن يَعۡشُ}؛ أي: يعرِضُ ويصدُّ {عن ذِكۡرِ الرحمن}: الذي هو القرآنُ العظيمُ، الذي هو أعظم رحمة رحم بها الرحمن عبادَه؛ فمن قَبِلَها؛ فقد قبل خير المواهب، وفاز بأعظم المطالب والرغائب، ومن أعرض عنها وردَّها؛ فقد خاب وخسِرَ خسارةً لا يسعدُ بعدها أبداً، وقيَّض له الرحمن شيطاناً مريداً يقارِنُه ويصاحِبُه ويعِدُه ويمنِّيه ويؤزُّه إلى المعاصي أزًّا","n":"الإعراض عن القرآن وذكر الله سبب لتسلط قرين من الشياطين.","en":"Allah informs of His severe punishment for one who turns away from His remembrance, so He said: \"And whoever turns away from the remembrance of the Most Merciful\" — that is, turns away and avoids the remembrance of the Most Merciful, which is the Great Quran, the greatest mercy with which the Most Merciful has shown mercy to His servants. Whoever accepts it has accepted the best of gifts and won the greatest of goals; whoever turns away and rejects it has lost with a loss after which he will never be happy. \"We appoint for him a devil\" — a rebellious devil who accompanies him, promises him, gives him false hopes and urges him on to sins.","ch":"x"},{"id":"q-muttaqi","w":"السعدي","bk":"saadi","s":7,"ay":201,"x":"ولما كان العبدُ لا بدَّ أن يغفل وينال منه الشيطان الذي لا يزال مرابطاً ينتظر غرَّته وغفلته؛ ذكر تعالى علامة المتَّقين من الغاوين، وأن المتَّقي إذا أحسَّ بذنب ومسَّه طائفٌ من الشيطان فأذنب بفعل محرَّم أو ترك واجبٍ؛ تذكَّر من أي باب أُتِيَ ومن أيِّ مدخل دخل الشيطان عليه، وتذكَّر ما أوجب الله عليه وما عليه من لوازم الإيمان، فأبصر، واستغفر الله تعالى، واستدرك ما فرط منه بالتوبة النصوح والحسنات الكثيرة، فرد شيطانه خاسئاً حسيراً","n":"علامة المتقي: إذا مسه طائف من الشيطان تذكر واستغفر فرد شيطانه خاسئاً.","en":"Since a servant must at times be heedless and receive from Satan, who stays on watch for his negligence, Allah mentioned the sign of the God-fearing as opposed to the misguided: when the God-fearing feels a sin and a touch from Satan reaches him, so that he sins by doing the forbidden or leaving an obligation, he remembers from which door he was approached and by which entrance Satan came in. He remembers what Allah made obligatory on him and what the requirements of faith are, so he sees clearly and seeks Allah's forgiveness, and makes good what he neglected by sincere repentance and many good deeds, so he drives his devil back, defeated and humiliated.","ch":"x"},{"id":"q-wasw","w":"السعدي","bk":"saadi","s":114,"ay":1,"x":"والوسواس كما يكون من الجنِّ يكون من الإنس","n":"الوسوسة قد تكون من الجن وقد تكون من الإنس، فيُتحصَّن من الصنفين.","en":"The whispering, as it comes from the jinn, comes from men.","ch":"x"},{"id":"q-sihr-batil","w":"السعدي","bk":"saadi","s":10,"ay":81,"x":"أي: هذا السحر الحقيقي العظيم، ولكن مع عظمته {إنَّ الله سيبطِلُه إنَّ الله لا يُصۡلِحُ عمل المفسدين}؛ فإنَّهم يريدون بذلك نصر الباطل على الحق، وأيُّ فساد أعظم من هذا؟! وهكذا كل مفسد عمل عملاً واحتال كيداً أو أتى بمكرٍ؛ فإنَّ عملَه سيبطُل ويضمحلُّ","n":"بطلان كيد السحر والمفسدين وأن عاقبته الاضمحلال.","en":"That is: this is the great real magic, but for all its greatness \"Allah will nullify it; Allah does not set right the work of the corrupters\", for they intend by it to support falsehood against truth, and what corruption is greater than this? So is every corrupter who does a deed, or devises a scheme or practises a trick: his work will be nullified and vanish.","ch":"x"},{"id":"q-sahir","w":"السعدي","bk":"saadi","s":20,"ay":69,"x":"أي: كيدهم ومكرهم ليس بمثمرٍ لهم ولا ناجح؛ فإنَّه من كيد السحرة الذين يموِّهون على الناس ويُلَبِّسون الباطل ويخيِّلون أنهم على الحقِّ","n":"الساحر لا يفلح، وكيده تمويه وتلبيس على الناس.","en":"That is: their scheme and their plotting is not fruitful for them or successful, for it is the scheme of magicians who deceive people, dress falsehood up and make them imagine that they are on the truth.","ch":"x"},{"id":"q-tawakkul","w":"السعدي","bk":"saadi","s":65,"ay":3,"x":"في أمر دينه ودنياه؛ بأن يعتمد على الله في جلب ما ينفعه ودفع ما يضرُّه ويثق به في تسهيل ذلك {فهو حسبُه}؛ أي: كافيه الأمر الذي توكَّل عليه فيه","n":"معنى التوكل الذي هو أصل التحصين: اعتماد القلب على الله مع فعل الأسباب.","en":"\"And whoever relies upon Allah\" in the matter of his religion and his worldly life, by depending on Allah in bringing what benefits him and warding off what harms him, and trusting Him to make that easy, \"then He is sufficient for him\" — that is, He suffices him in the matter in which he relied on Him.","ch":"x"},{"id":"q-yadurr","w":"السعدي","bk":"saadi","s":58,"ay":10,"x":"وليس بضارِّهم شيئاً إلاَّ بإذنِ الله}: فإنَّ الله [تعالى] وَعَدَ المؤمنين بالكفاية والنصر على الأعداء، وقال تعالى:{ولا يَحيقُ المكرُ السيِّئُ إلاَّ بأهلِهِ}: فأعداء الله ورسوله والمؤمنين مهما تَناجَوْا ومَكَروا؛ فإنَّ ضَرَرَ ذلك عائدٌ إلى أنفسهم ، ولا يضرُّ المؤمنين إلاَّ شيءٌ قدَّره الله وقضاه. {وعلى الله فَلۡيَتَوَكَّلِ المؤمنون}؛ أي: ليعتمدوا عليه ويَثِقوا بوعده","n":"لا يضر المؤمنين إلا ما قدّره الله، وعليهم أن يتوكلوا ويثقوا بوعده.","en":"\"And it will not harm them at all except by permission of Allah\": Allah has promised the believers sufficiency and victory over their enemies... and nothing harms the believers except something Allah has decreed and ordained. \"And upon Allah let the believers rely\" — that is, let them depend on Him and trust His promise.","ch":"x"},{"id":"q-ghayb","w":"السعدي","bk":"saadi","s":72,"ay":26,"x":"فعلمُ ذلك عند الله {عالمُ الغيب فلا يُظۡهِرُ على غيبِهِ أحداً}:\nمن الخلق، بل انفرد بعلم الضمائر والأسرار والغيوب","n":"علم الغيب لله وحده، فمن ادعاه فقد كذب.","en":"So knowledge of that is with Allah: \"Knower of the unseen; He does not disclose His unseen to anyone\" of creation, but He alone has knowledge of hidden thoughts, secrets and unseen things.","ch":"x"},{"id":"q-kathir-sihr","w":"ابن كثير","bk":"ibnkathir","s":2,"ay":102,"x":"وَلِهَذَا أَرَادُوا كيْدًا بِرَسُولِ اللَّهِ ﷺ وسَحَروه في مُشْط ومُشَاقة وجُفّ طَلْعَة ذَكر، تَحْتَ رَاعُوثَةِ بِئْرِ ذِي أَرْوَانَ. وَكَانَ الذِي تَوَلَّى ذَلِكَ مِنْهُمْ رَجُلٌ، يُقَالُ لَهُ: لَبِيدُ بْنُ الْأَعْصَمِ، لَعَنَهُ اللَّهُ، فَأَطْلَعَ اللَّهُ عَلَى ذَلِكَ رَسُولَهُ ﷺ، وَشَفَاهُ مِنْهُ وَأَنْقَذَهُ، كَمَا ثَبَتَ ذَلِكَ مَبْسُوطًا فِي الصَّحِيحَيْنِ عَنْ عَائِشَةَ أُمِّ الْمُؤْمِنِينَ","n":"ذكر سحر النبي ﷺ، وأن الله أطلعه عليه وشفاه منه.","en":"Therefore they plotted against the Messenger of Allah ﷺ and bewitched him with a comb, the combings and the spathe of a male palm, beneath the stone at the bottom of the well of Dhi Arwan. The one who carried that out among them was a man called Labid ibn al-A'sam, may Allah curse him. Allah informed His Messenger ﷺ of it and healed him and rescued him, as is established in detail in the two Sahihs from 'A'ishah, Mother of the Believers.","ch":"x"}],"rules":[["أن تكون بكلام الله أو بأسمائه وصفاته أو بالأدعية المأثورة","كالفاتحة والمعوذات وآية الكرسي، و«أذهب الباس رب الناس»، و«بسم الله أرقيك»؛ فهذا أعلى الرقى وأبعدها عن الشبهة.","It must be with the words of Allah, His names and attributes, or transmitted supplications","Such as al-Fatihah, the surahs of refuge, Ayat al-Kursi, \"Remove the harm, Lord of mankind\" and \"In the name of Allah I perform ruqyah for you\"; these are the highest forms of ruqyah and the furthest from doubt."],["أن تكون بلسان مفهوم المعنى","بالعربية أو بما يُعرف معناه من غيرها، فلا تجوز بالطلاسم والحروف المقطعة والأسماء المجهولة التي لا يُدرى ما هي.","It must be in words whose meaning is understood","In Arabic or in a language whose meaning is known; ruqyah with talismans, disjointed letters and unknown names is not permitted."],["أن يُعتقد أن الشفاء من الله وحده","الرقية سبب لا يؤثر بذاته، والشافي هو الله: «وإذا مرضت فهو يشفين».","One must believe that healing is from Allah alone","Ruqyah is a means that has no effect by itself; Allah is the Healer: \"And when I am ill, it is He who heals me\"."],["أن تخلو من الشرك والمحرّم","قال النبي ﷺ: «لا بأس بالرقى ما لم يكن فيه شرك»، فلا استغاثة بغير الله، ولا ذبح لغيره، ولا استعانة بالجن.","It must be free of shirk and anything forbidden","The Prophet ﷺ said: \"There is no harm in ruqyah as long as it contains no shirk.\" So no calling on other than Allah, no sacrifice to other than Him, and no seeking help from jinn."],["ألا تكون بهيئة محرّمة","كالرقية في الأماكن النجسة، أو مع خلوة بامرأة أجنبية أو مس ما لا يحل مسه، أو بإيذاء المريض بالضرب والخنق.","It must not be performed in a forbidden manner","Such as in impure places, in seclusion with a non-mahram woman or touching what may not be touched, or harming the patient by beating or choking."],["ألا تُترك بها الأسباب المشروعة","الرقية لا تغني عن الطبيب، والنبي ﷺ رقى وتداوى وأمر بالتداوي، فيجمع المسلم بين الأمرين.","It must not replace lawful means","Ruqyah does not replace the physician. The Prophet ﷺ performed ruqyah, sought treatment and commanded it, so a Muslim combines both."]],"steps":[["أخلص النية وأحسن الظن بالله","استحضر أن الشافي هو الله، وأن القرآن شفاء لمن آمن به، واستعن بالتوبة والاستغفار والصدقة.","Make your intention sincere and think well of Allah","Keep in mind that Allah is the Healer and that the Quran is healing for those who believe in it, and support this with repentance, seeking forgiveness and charity."],["ضع يدك على موضع الألم","وقل: «بسم الله» ثلاثاً، ثم «أعوذ بالله وقدرته من شر ما أجد وأحاذر» سبع مرات، كما في حديث عثمان بن أبي العاص.","Place your hand on the place of pain","Say \"In the name of Allah\" three times, then \"I seek refuge in Allah and His power from the evil of what I feel and what I fear\" seven times, as in the hadith of 'Uthman ibn Abi al-'As."],["اقرأ الفاتحة والمعوذات وآية الكرسي","وما تيسر من آيات الشفاء وخواتيم البقرة، مع النفث الخفيف، وهو نفخ لطيف معه شيء يسير من الريق.","Recite al-Fatihah, the surahs of refuge and Ayat al-Kursi","And whatever is easy of the verses of healing and the end of al-Baqarah, blowing lightly, a gentle breath with a little moisture."],["امسح بيدك على جسدك","اجمع كفيك وانفث فيهما واقرأ الإخلاص والمعوذتين، ثم امسح ما استطعت من جسدك، ثلاث مرات.","Wipe your body with your hand","Join your palms, blow lightly into them and recite al-Ikhlas and the two surahs of refuge, then wipe as much of your body as you can, three times."],["ادع بالأدعية النبوية","«اللهم رب الناس، أذهب الباس، اشفه وأنت الشافي، لا شفاء إلا شفاؤك، شفاء لا يغادر سقماً».","Supplicate with the prophetic supplications","\"O Allah, Lord of mankind, remove the harm; heal him, for You are the Healer; there is no healing but Your healing, a healing that leaves no illness behind.\""],["داوم على التحصين واستمر في العلاج","أذكار الصباح والمساء والنوم حصن يومي، والمتابعة مع الطبيب واجبة على من احتاج إليها.","Keep up protection and continue treatment","The morning, evening and bedtime remembrances are a daily fortress, and following up with a physician is a duty for anyone who needs it."]],"warn":[["ترك العلاج الطبي","من الخطأ الاكتفاء بالرقية في الأمراض العضوية والنفسية وترك الطبيب، والسنة الجمع بينهما.","Abandoning medical treatment","It is a mistake to rely on ruqyah alone for physical and mental illnesses and abandon the physician; the Sunnah is to combine both."],["التمائم والحروز والطلاسم","تعليق الخيوط والخرز والطلاسم لدفع العين أو جلب النفع من الشرك المنهي عنه.","Amulets, charms and talismans","Hanging threads, beads and talismans to ward off the evil eye or bring benefit is a form of forbidden shirk."],["إتيان السحرة والكهنة والعرافين","ومن علاماتهم: السؤال عن اسم الأم، وطلب أثر من المريض، والذبح لغير الله، والكلام بغير المفهوم، والإخبار بالغيب.","Going to sorcerers, soothsayers and fortune-tellers","Their signs include asking for the mother's name, requesting an item of the patient's, sacrificing to other than Allah, speaking unintelligible words and claiming knowledge of the unseen."],["المبالغة في نسبة كل مرض إلى العين أو المس","كثير من الأعراض لها أسباب طبية ونفسية تحتاج إلى تشخيص، والاستعجال في نسبتها إلى المس يؤخر العلاج ويضر المريض.","Attributing every illness to the evil eye or possession","Many symptoms have medical and psychological causes that need diagnosis; hastily attributing them to possession delays treatment and harms the patient."],["الإيذاء والاستغلال باسم الرقية","الضرب والخنق والصعق، والمغالاة في الأجور، وبيع مياه وزيوت بأثمان باهظة بدعوى الخصوصية، كلها مما لا يقره الشرع.","Harm and exploitation in the name of ruqyah","Beating, choking, electric shocks, excessive fees, and selling water and oils at exorbitant prices on claims of special power are all things the Shariah does not approve."]]};
